type PublicationAttempt = "initial" | "recovery";
type PublicationFailureCategory =
  | "timeout"
  | "permission_denied"
  | "publish_permission_denied"
  | "device_not_found"
  | "device_in_use"
  | "media_device"
  | "publish"
  | "unknown";

const terminalPublicationFailures = new Set<PublicationFailureCategory>([
  "permission_denied",
  "publish_permission_denied",
  "device_not_found",
  "device_in_use",
]);

interface DestructionDeadline {
  readonly reached: Promise<void>;
  cancel(): void;
}

type CreateDestructionDeadline = () => DestructionDeadline;
type PublicationTrack = NonNullable<LocalTrackPublication["track"]>;

interface SourcePublicationFailure {
  readonly source: Track.Source;
  readonly error: unknown;
}

interface SourceRecoveryState {
  readonly lossGeneration: number;
  attempts: number;
}

interface SourceRecoveryTimer {
  readonly lossGeneration: number;
  readonly timeout: ReturnType<typeof setTimeout>;
}

interface PublicationTrackOwner {
  readonly tracks: Set<PublicationTrack>;
  canAcquireTrack(track: PublicationTrack): boolean;
  acquiredTrack(track: PublicationTrack): void;
  releasedTrack(track: PublicationTrack): void;
  cleanupTimedOutTrack(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void;
  cleanupLateTrackMutation(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void;
}

interface LatePublicationObserver {
  retire(successor?: PublicationTrackOwner): void;
}

class CombinedCaptureFailure {
  public constructor(public readonly cause: unknown) {}
}

class SourcePublicationFailures {
  public constructor(
    public readonly failures: readonly SourcePublicationFailure[],
  ) {}
}

type PublicationTrackCleanupBoundary = "unpublished" | "settled" | "deadline";

interface PublicationTrackCleanupResult {
  readonly publication: LocalTrackPublication | undefined;
  readonly boundary: PublicationTrackCleanupBoundary;
}

interface PublicationTrackCleanup {
  readonly generation: MediaStreamTrack;
  readonly operation: Promise<LocalTrackPublication | undefined>;
  readonly safePoint: Promise<PublicationTrackCleanupBoundary>;
  readonly result: Promise<PublicationTrackCleanupResult>;
  mutationObserved: boolean;
  deadlineReached: boolean;
}

interface PublicationTrackGenerationState {
  stopped: boolean;
  unsafeMutation: boolean;
}

interface PublicationTrackGeneration {
  readonly track: PublicationTrack;
  readonly generation: MediaStreamTrack;
  readonly senderBindings?: readonly PublicationSenderBinding[];
}

interface PublicationSenderBinding {
  readonly sender: RTCRtpSender;
  readonly expectedTrack: MediaStreamTrack;
  readonly current: boolean;
}

interface PendingLocalSender {
  readonly track: PublicationTrack;
  readonly generation: MediaStreamTrack;
}

interface PendingTrackSenderObservation {
  readonly track: PublicationTrack;
  readonly expectedTrack: MediaStreamTrack;
}

interface SenderFenceOperation {
  readonly track: PublicationTrack;
  readonly operation: Promise<void>;
}

interface SenderAssignmentTrack {
  setSimulcastTrackSender?: (codec: unknown, sender: RTCRtpSender) => void;
}

interface SenderAssignmentObservation {
  readonly senderTrack: SenderAssignmentTrack;
  readonly original: (codec: unknown, sender: RTCRtpSender) => void;
  readonly wrapper: (codec: unknown, sender: RTCRtpSender) => void;
  readonly hadOwnMethod: boolean;
}

interface PublicationTrackObservation {
  readonly mediaGenerations: Set<MediaStreamTrack>;
  readonly trackHandlers: ReadonlyMap<TrackEvent, () => void>;
  readonly mediaStateHandler: () => void;
  readonly senderAssignment?: SenderAssignmentObservation;
}

interface ScreenShareOperation {
  readonly owner: PublicationTrackOwner;
  readonly tracks: Set<PublicationTrack>;
  readonly senderFenceOperations: Set<Promise<void>>;
  readonly settled: Promise<void>;
  readonly settle: () => void;
  retired: boolean;
}

const publicationTrackOwners = new WeakMap<
  PublicationTrack,
  PublicationTrackOwner
>();
const publicationTrackDetachOperations = new WeakMap<
  PublicationTrack,
  Set<Promise<void>>
>();
const publicationTrackSenderTargets = new WeakMap<
  PublicationTrack,
  Map<RTCRtpSender, MediaStreamTrack>
>();
const publicationTrackGenerationStates = new WeakMap<
  PublicationTrack,
  WeakMap<MediaStreamTrack, PublicationTrackGenerationState>
>();
const publicationTrackCleanups = new WeakMap<
  PublicationTrack,
  Set<PublicationTrackCleanup>
>();
const participantPublicationGenerations = new WeakMap<
  LocalParticipant,
  object
>();
const latePublicationObservers = new WeakMap<
  LocalParticipant,
  LatePublicationObserver
>();
const participantScreenShareOperations = new WeakMap<
  LocalParticipant,
  Set<ScreenShareOperation>
>();

function getParticipantScreenShareOperation(
  participant: LocalParticipant,
  track: PublicationTrack,
): ScreenShareOperation | undefined {
  return [...(participantScreenShareOperations.get(participant) ?? [])].find(
    (operation) => operation.tracks.has(track),
  );
}

async function registerPublicationTrackDetachOperation<T>(
  track: PublicationTrack,
  operation: Promise<T>,
): Promise<T> {
  let operations = publicationTrackDetachOperations.get(track);
  if (!operations) {
    operations = new Set();
    publicationTrackDetachOperations.set(track, operations);
  }
  const settled = operation.then(
    () => undefined,
    () => undefined,
  );
  operations.add(settled);
  void settled.then(() => {
    operations.delete(settled);
    if (operations.size === 0) {
      publicationTrackDetachOperations.delete(track);
    }
  });
  return await operation;
}

async function transferPublicationTrackOwnership(
  track: PublicationTrack,
  owner: PublicationTrackOwner,
): Promise<boolean> {
  while (publicationTrackOwners.get(track) !== owner) {
    const detachOperations = [
      ...(publicationTrackDetachOperations.get(track) ?? []),
    ];
    if (detachOperations.length > 0) {
      await Promise.all(detachOperations);
      continue;
    }
    const currentOwner = publicationTrackOwners.get(track);
    if (!owner.canAcquireTrack(track)) return false;
    currentOwner?.tracks.delete(track);
    currentOwner?.releasedTrack(track);
    publicationTrackOwners.set(track, owner);
    owner.tracks.add(track);
    owner.acquiredTrack(track);
  }
  return true;
}

const destructionGracePeriodMs = 5_000;
const maximumAutomaticRecoveryAttempts = 3;
const automaticRecoveryBaseDelayMs = 100;

const createDefaultDestructionDeadline = (): DestructionDeadline => {
  let timeout: ReturnType<typeof setTimeout> | undefined;
  const reached = new Promise<void>((resolve) => {
    timeout = setTimeout(resolve, destructionGracePeriodMs);
  });
  return {
    reached,
    cancel: (): void => {
      if (timeout !== undefined) clearTimeout(timeout);
      timeout = undefined;
    },
  };
};

function classifyPublicationFailure(
  error: unknown,
): PublicationFailureCategory {
  if (error instanceof PublishTrackError) {
    if (error.status === 403) return "publish_permission_denied";
    return error.status === 408 ? "timeout" : "publish";
  }
  if (typeof error !== "object" || error === null) return "unknown";

  switch (MediaDeviceFailure.getFailure(error)) {
    case MediaDeviceFailure.PermissionDenied:
      return "permission_denied";
    case MediaDeviceFailure.NotFound:
      return "device_not_found";
    case MediaDeviceFailure.DeviceInUse:
      return "device_in_use";
    case MediaDeviceFailure.Other:
      return "media_device";
    default:
      return "unknown";
  }
}

function selectPublicationFailure(
  failures: readonly SourcePublicationFailure[],
): unknown {
  return (
    failures.find(({ error }) =>
      terminalPublicationFailures.has(classifyPublicationFailure(error)),
    )?.error ?? failures[0]?.error
  );
}

async function registerPublicationTrackCleanup(
  track: PublicationTrack,
  generation: MediaStreamTrack,
  participant: LocalParticipant,
  cleanup: () => Promise<LocalTrackPublication | undefined>,
  deadline: DestructionDeadline,
): Promise<PublicationTrackCleanupResult> {
  let cleanups = publicationTrackCleanups.get(track);
  const existingCleanup = [...(cleanups ?? [])].find(
    (candidate) => candidate.generation === generation,
  );
  if (existingCleanup) {
    deadline.cancel();
    return await existingCleanup.result;
  }

  const unpublished = Promise.withResolvers<void>();
  const operation = Promise.resolve().then(cleanup);
  const settled = operation.then(
    () => undefined,
    () => undefined,
  );
  const safePoint = Promise.race([
    unpublished.promise.then(() => "unpublished" as const),
    settled.then(() => "settled" as const),
    deadline.reached.then(() => "deadline" as const),
  ]).then((outcome) => {
    deadline.cancel();
    if (outcome === "deadline") {
      registration.deadlineReached = true;
    }
    return outcome;
  });
  const result = Promise.race([
    operation.then((publication) => ({
      publication,
      boundary: "settled" as const,
    })),
    unpublished.promise.then(() => ({
      publication: undefined,
      boundary: "unpublished" as const,
    })),
    deadline.reached.then(() => ({
      publication: undefined,
      boundary: "deadline" as const,
    })),
  ]);
  const registration: PublicationTrackCleanup = {
    generation,
    operation,
    safePoint,
    result,
    mutationObserved: false,
    deadlineReached: false,
  };
  const unpublishedHandler = (publication: LocalTrackPublication): void => {
    if (publication.track === track) {
      registration.mutationObserved = true;
      unpublished.resolve();
    }
  };
  participant.on(ParticipantEvent.LocalTrackUnpublished, unpublishedHandler);
  if (!cleanups) {
    cleanups = new Set();
    publicationTrackCleanups.set(track, cleanups);
  }
  cleanups.add(registration);
  void safePoint.then(() => {
    participant.off(ParticipantEvent.LocalTrackUnpublished, unpublishedHandler);
  });
  void settled.then(() => {
    cleanups.delete(registration);
    if (cleanups.size === 0) publicationTrackCleanups.delete(track);
    if (registration.deadlineReached) {
      publicationTrackOwners
        .get(track)
        ?.cleanupTimedOutTrack(track, generation);
    }
  });
  try {
    return await result;
  } finally {
    participant.off(ParticipantEvent.LocalTrackUnpublished, unpublishedHandler);
  }
}

function getPublicationTrackGenerationState(
  track: PublicationTrack,
  generation = track.mediaStreamTrack,
): PublicationTrackGenerationState {
  let generations = publicationTrackGenerationStates.get(track);
  if (!generations) {
    generations = new WeakMap();
    publicationTrackGenerationStates.set(track, generations);
  }
  let state = generations.get(generation);
  if (!state) {
    state = { stopped: false, unsafeMutation: false };
    generations.set(generation, state);
  }
  return state;
}

function isPublicationTrackGenerationStopped(
  track: PublicationTrack,
  generation = track.mediaStreamTrack,
): boolean {
  return (
    getPublicationTrackGenerationState(track, generation).stopped ||
    generation.readyState === "ended"
  );
}

function getPublicationTrackCleanups(
  track: PublicationTrack,
): readonly PublicationTrackCleanup[] {
  return [...(publicationTrackCleanups.get(track) ?? [])];
}

function hasUnsafePendingTrackMutation(track: PublicationTrack): boolean {
  return getPublicationTrackCleanups(track).some(
    (cleanup) => !cleanup.mutationObserved,
  );
}

/**
 * A wrapper for a Connection object.
 * This wrapper will manage the connection used to publish to the LiveKit room.
 * The Publisher is also responsible for creating the media tracks.
 */
export class Publisher {
  /**
   * By default, livekit will start publishing tracks as soon as they are created.
   * In the matrix RTC world, we want to control when tracks are published based
   * on whether the user is part of the RTC session or not.
   */
  private readonly publishingActiveSubject$ = new BehaviorSubject(false);

  /** Whether the selected exact upstreams are currently active. */
  public readonly publishingActive$: Behavior<boolean> =
    this.publishingActiveSubject$;

  public get shouldPublish(): boolean {
    return this.publishingActiveSubject$.value;
  }

  /** Whether every currently requested microphone/camera source is published. */
  public readonly requestedSourcesPublished$: Behavior<boolean>;

  private readonly scope = new ObservableScope();
  private readonly publicationChanged$ = new Subject<void>();
  private readonly mediaOperations = new Set<Promise<void>>();
  private readonly cleanupOperations = new Set<Promise<void>>();
  private readonly sourceEnableOperations = new Map<
    Track.Source,
    Set<Promise<void>>
  >();
  private readonly sourceReconciliationTails = new Map<
    Track.Source,
    Promise<void>
  >();
  private readonly desiredSourceEnabled = new Map<Track.Source, boolean>();
  private readonly ownedTracks = new Set<PublicationTrack>();
  private readonly preferredSourceTracks = new Map<
    Track.Source,
    { readonly track: PublicationTrack; readonly generation: MediaStreamTrack }
  >();
  private readonly processorOperationTracks = new WeakMap<
    LocalVideoTrack,
    WeakMap<MediaStreamTrack, LocalVideoTrack>
  >();
  private readonly queuedTrackReaperGenerations = new Map<
    PublicationTrack,
    Set<MediaStreamTrack>
  >();
  private readonly cleanupRetryGenerations = new Map<
    PublicationTrack,
    MediaStreamTrack
  >();
  private readonly trackObservations = new Map<
    PublicationTrack,
    PublicationTrackObservation
  >();
  private readonly trackControlOperations = new Map<
    PublicationTrack,
    Promise<void>
  >();
  private readonly startingTrackControlOperations = new Set<PublicationTrack>();
  private readonly controlledPausedGenerations = new WeakMap<
    PublicationTrack,
    WeakSet<MediaStreamTrack>
  >();
  private readonly authoritativeResumeGenerations = new WeakMap<
    PublicationTrack,
    WeakSet<MediaStreamTrack>
  >();
  private readonly committedPublicationGenerations = new WeakMap<
    PublicationTrack,
    WeakSet<MediaStreamTrack>
  >();
  private readonly trackOwnershipOperations = new Set<Promise<void>>();
  private readonly pendingLocalSenders = new Map<
    RTCRtpSender,
    PendingLocalSender
  >();
  private readonly pendingTrackSenderObservations = new Map<
    RTCRtpSender,
    PendingTrackSenderObservation
  >();
  private readonly senderFenceOperations = new Map<
    RTCRtpSender,
    SenderFenceOperation
  >();
  private readonly trackMutationOperationCounts = new Map<
    PublicationTrack,
    number
  >();
  private readonly screenShareOperations = new Set<ScreenShareOperation>();
  private readonly publicationGeneration = {};
  private readonly trackOwner: PublicationTrackOwner = {
    tracks: this.ownedTracks,
    canAcquireTrack: (track): boolean =>
      participantPublicationGenerations.get(
        this.connection.livekitRoom.localParticipant,
      ) === this.publicationGeneration ||
      [...this.screenShareOperations].some(
        (operation) => operation.retired && operation.tracks.has(track),
      ),
    acquiredTrack: (track): void => this.observeTrackState(track),
    releasedTrack: (track): void => this.stopObservingTrackState(track),
    cleanupTimedOutTrack: (track, generation): void => {
      this.onTimedOutTrackCleanupSettled(track, generation);
    },
    cleanupLateTrackMutation: (track, generation): void => {
      this.onLateTrackMutationSettled(track, generation);
    },
  };
  private readonly sourceLossGenerations = new Map<Track.Source, number>();
  private readonly recoveryStates = new Map<
    Track.Source,
    SourceRecoveryState
  >();
  private readonly recoveryTimers = new Map<
    Track.Source,
    SourceRecoveryTimer
  >();
  private readonly automaticRecoveryBlockedSources = new Set<Track.Source>();
  private setupStarted = false;
  private initialPublicationPending = false;
  private destroyed = false;
  private destroyPromise: Promise<void> | undefined;
  private destructionFinished = false;
  private lateCleanupQueued = false;
  private terminallyDisconnected = false;
  private publishingRequested = false;
  private matrixRTCConnected = true;
  private publishingControlGeneration = 0;
  private startPublishingOperation: Promise<void> | undefined;
  private publishingReconciliationQueued = false;

  private readonly localTrackPublishedHandler = (
    publication: LocalTrackPublication,
  ): void => {
    this.onLocalTrackPublished(publication);
  };

  private readonly localTrackUnpublishedHandler = (
    publication: LocalTrackPublication,
  ): void => {
    this.onLocalTrackUnpublished(publication);
  };

  private readonly localSenderCreatedHandler = (
    sender: RTCRtpSender,
    track: Track,
  ): void => {
    this.onLocalSenderCreated(sender, track as PublicationTrack);
  };

  private readonly roomConnectedHandler = (): void => {
    if (this.destroyed || this.terminallyDisconnected) return;
    this.reapUnusablePublications();
    for (const source of this.getRequestedSources()) {
      if (
        !this.getResumablePublication(source) &&
        !this.sourceEnableOperations.has(source) &&
        !this.automaticRecoveryBlockedSources.has(source)
      ) {
        this.cancelSourceRecoveryTimer(source);
        this.recoveryStates.delete(source);
      }
    }
    this.recoverMissingRequestedSources();
  };

  private readonly roomDisconnectedHandler = (): void => {
    this.handleTerminalDisconnect();
  };

  /**
   * Creates a new Publisher.
   * @param connection - The connection to use for publishing.
   * @param devices - The media devices to use for audio and video input.
   * @param muteStates - The mute states for audio and video.
   * @param trackerProcessorState$ - The processor state for the video track processor (e.g. background blur).
   * @param logger - The logger to use for logging :D.
   */
  public constructor(
    private connection: Pick<Connection, "livekitRoom" | "state$">, //setE2EEEnabled,
    devices: MediaDevices,
    private readonly muteStates: MuteStates,
    trackerProcessorState$: Behavior<ProcessorState>,
    private logger: Logger,
    private readonly createDestructionDeadline: CreateDestructionDeadline = createDefaultDestructionDeadline,
    private readonly createCleanupSafePointDeadline: CreateDestructionDeadline = createDefaultDestructionDeadline,
    private readonly createUpstreamControlDeadline: CreateDestructionDeadline = createDefaultDestructionDeadline,
  ) {
    const { controlledAudioDevices } = getUrlParams();
    const room = connection.livekitRoom;
    const localParticipant = room.localParticipant;

    localParticipant.on(
      ParticipantEvent.LocalTrackPublished,
      this.localTrackPublishedHandler,
    );
    localParticipant.on(
      ParticipantEvent.LocalTrackUnpublished,
      this.localTrackUnpublishedHandler,
    );
    localParticipant.on(
      ParticipantEvent.LocalSenderCreated,
      this.localSenderCreatedHandler,
    );
    room.on(LivekitRoomEvent.Disconnected, this.roomDisconnectedHandler);
    participantPublicationGenerations.set(
      localParticipant,
      this.publicationGeneration,
    );
    latePublicationObservers.get(localParticipant)?.retire(this.trackOwner);

    const inheritedTracks = [...this.getPublishedTracks()];
    inheritedTracks.forEach((track) => {
      this.markPublicationCommitted(track, track.mediaStreamTrack);
      this.claimTrack(track, true);
    });
    const inheritedSources = [
      ...new Set(
        inheritedTracks
          .filter((track) => this.ownsTrack(track) && this.isTrackUsable(track))
          .map((track) => track.source),
      ),
    ];
    if (inheritedSources.length > 0) {
      void this.ownMediaOperation(
        this.pauseUpstreams(room, inheritedSources),
      ).catch(() => {
        this.logger.error("Failed to pause inherited local media");
      });
    }

    this.desiredSourceEnabled.set(
      Track.Source.Microphone,
      this.muteStates.audio.enabled$.value,
    );
    this.desiredSourceEnabled.set(
      Track.Source.Camera,
      this.muteStates.video.enabled$.value,
    );

    this.requestedSourcesPublished$ = this.scope.behavior(
      combineLatest([
        this.muteStates.audio.enabled$,
        this.muteStates.video.enabled$,
        this.publicationChanged$.pipe(startWith(undefined)),
      ]).pipe(
        map(
          ([audio, video]) =>
            this.getRequestedSources(audio, video).every((source) =>
              this.hasPublication(source),
            ) && !this.hasUncontrolledPublications(),
        ),
      ),
    );

    room.on(LivekitRoomEvent.Connected, this.roomConnectedHandler);
    room.on(LivekitRoomEvent.Reconnected, this.roomConnectedHandler);

    void this.registerMediaOperation(
      room.setE2EEEnabled(room.options.e2ee !== undefined),
    ).catch(() => {
      this.logger.error("Failed to set E2EE enabled on room");
    });

    // Setup track processor syncing (blur)
    this.observeTrackProcessors(this.scope, trackerProcessorState$);
    // Observe media device changes and update LiveKit active devices accordingly
    this.observeMediaDevices(this.scope, devices, controlledAudioDevices);

    this.workaroundRestartAudioInputTrackChrome(devices, this.scope);
    this.reapUnusablePublications();
  }

  public async destroy(): Promise<void> {
    if (this.destroyPromise) return this.destroyPromise;

    this.destroyed = true;
    this.pendingTrackSenderObservations.clear();
    this.cancelSourceRecoveryTimers();
    this.retireScreenShareOperations();
    this.cancelPublishingIntent();
    const pendingSenderFence = this.fencePendingLocalSenders();
    void pendingSenderFence.catch(() => {
      this.logger.error(
        "Failed to fence pending local media during destruction",
      );
    });
    const room = this.connection.livekitRoom;
    room.off(LivekitRoomEvent.Connected, this.roomConnectedHandler);
    room.off(LivekitRoomEvent.Reconnected, this.roomConnectedHandler);
    this.scope.end();
    this.logger.info("Scope ended -> unset handler");
    this.muteStates.audio.unsetHandler();
    this.muteStates.video.unsetHandler();
    this.claimPublishedTracksForDestruction();
    this.forceStopKnownTracks();
    this.setPublishingActive(false);
    this.publicationChanged$.next();

    this.destroyPromise = this.destroyInternal();
    return this.destroyPromise;
  }

  private async destroyInternal(): Promise<void> {
    const deadline = this.createDestructionDeadline();
    let deadlineReached = false;
    const deadlineReachedPromise = deadline.reached.then(() => {
      deadlineReached = true;
    });

    try {
      await this.waitForOperationsOrDeadline(
        this.mediaOperations,
        deadlineReachedPromise,
        () => deadlineReached,
      );

      this.claimPublishedTracksForDestruction();
      this.stopOwnedUnpublishedTracks();
      this.logger.info("Start to stop tracks");
      this.startCleanupAttempt();
      await this.waitForOperationsOrDeadline(
        this.cleanupOperations,
        deadlineReachedPromise,
        () => deadlineReached,
      );
      if (deadlineReached) this.forceStopKnownTracks();
      this.logger.info("Done to stop tracks");
    } finally {
      deadline.cancel();
      this.destructionFinished = true;
      this.claimPublishedTracksForDestruction();
      if (
        deadlineReached ||
        this.mediaOperations.size > 0 ||
        this.cleanupOperations.size > 0 ||
        this.ownedTracks.size > 0
      ) {
        this.forceStopKnownTracks();
        this.queueLateCleanup();
      }
      const room = this.connection.livekitRoom;
      const participant = room.localParticipant;
      participant.off(
        ParticipantEvent.LocalTrackPublished,
        this.localTrackPublishedHandler,
      );
      participant.off(
        ParticipantEvent.LocalTrackUnpublished,
        this.localTrackUnpublishedHandler,
      );
      participant.off(
        ParticipantEvent.LocalSenderCreated,
        this.localSenderCreatedHandler,
      );
      this.observeLatePublicationsAfterDestruction(room);
      room.off(LivekitRoomEvent.Disconnected, this.roomDisconnectedHandler);
    }
  }

  // LiveKit will publish the tracks as soon as they are created
  // but we want to control when tracks are published.
  // We cannot just mute the tracks, even if this will effectively stop the publishing,
  // it would also prevent the user from seeing their own video/audio preview.
  // So for that we use pauseUpStream():  Stops sending media to the server by replacing
  // the sender track with null, but keeps the local MediaStreamTrack active.
  // The user can still see/hear themselves locally, but remote participants see nothing.
  private onLocalSenderCreated(
    sender: RTCRtpSender,
    track: PublicationTrack,
  ): void {
    const participant = this.connection.livekitRoom.localParticipant;
    if (getParticipantScreenShareOperation(participant, track)) return;
    if (!this.trackOwner.canAcquireTrack(track)) return;
    if (!this.ownsTrack(track)) {
      this.pendingTrackSenderObservations.set(sender, {
        track,
        expectedTrack: this.getSenderAssignmentTarget(
          track,
          track.mediaStreamTrack,
          sender,
        ),
      });
      this.publicationChanged$.next();
      this.claimTrack(track, true);
      return;
    }
    this.onTrackSenderDiscovered(track, sender);
  }

  private onTrackSenderDiscovered(
    track: PublicationTrack,
    sender: RTCRtpSender,
    expectedTrack?: MediaStreamTrack,
  ): void {
    if (!this.ownsTrack(track) || !this.trackOwner.canAcquireTrack(track)) {
      return;
    }
    const generation = track.mediaStreamTrack;
    if (expectedTrack) {
      this.getSenderTargets(track).set(sender, expectedTrack);
    } else {
      this.recordSenderAssignment(track, generation, sender);
    }
    if (!this.getExactPublication(track)) {
      this.pendingLocalSenders.set(sender, { track, generation });
    }
    this.getTrackSenderBindings(track, generation);

    if (!this.isTrackSenderRequested(track, generation)) {
      const operation = this.fenceLocalSender(track, generation, sender);
      void operation.catch(() => {
        this.logger.error("Failed to fence a newly created local media sender");
      });
    }
    if (this.destroyed || this.terminallyDisconnected) {
      this.stopOwnedTrackGeneration(track, generation);
    }
    this.publicationChanged$.next();
  }

  private isTrackSenderRequested(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): boolean {
    const exactPublication = this.getExactPublication(track);
    const publicationCommitted =
      this.isPublicationCommitted(track, generation) && !!exactPublication;
    const publicationPending =
      !this.isPublicationCommitted(track, generation) &&
      !exactPublication &&
      this.sourceEnableOperations.has(track.source);
    if (
      !this.isPublishingIntentCurrent() ||
      !this.ownsTrack(track) ||
      track.mediaStreamTrack !== generation ||
      (!publicationCommitted && !publicationPending) ||
      this.isControlledPausedGeneration(track, generation) ||
      this.isAuthoritativeResumeGeneration(track, generation) ||
      this.trackControlOperations.has(track) ||
      this.hasPendingTrackMutationOperation(track) ||
      !this.isTrackHealthy(track)
    ) {
      return false;
    }
    return (
      (track.source !== Track.Source.Microphone &&
        track.source !== Track.Source.Camera) ||
      this.getDesiredSourceEnabled(track.source)
    );
  }

  private async fenceLocalSender(
    track: PublicationTrack,
    generation: MediaStreamTrack,
    sender: RTCRtpSender,
  ): Promise<void> {
    const existingOperation = this.senderFenceOperations.get(sender);
    if (existingOperation) return await existingOperation.operation;
    if (sender.track === null) return Promise.resolve();

    const detachOperation = this.replaceSenderTrackWithDeadline(
      sender,
      null,
      undefined,
      { track, generation },
    );
    const operation = this.ownMediaOperation(
      (async (): Promise<void> => {
        try {
          await detachOperation;
          if (sender.track !== null) {
            throw new Error("An exact local media sender remained attached");
          }
        } catch (error) {
          if (this.ownsTrack(track)) {
            this.stopOwnedTrackGeneration(track, generation);
            if (this.getExactPublication(track)) {
              this.queueTrackReaper(track, track.mediaStreamTrack);
            }
          }
          throw error;
        }
      })(),
    );
    const registration: SenderFenceOperation = { track, operation };
    this.senderFenceOperations.set(sender, registration);
    const settled = (): void => {
      if (this.senderFenceOperations.get(sender) === registration) {
        this.senderFenceOperations.delete(sender);
      }
      this.publicationChanged$.next();
    };
    void operation.then(settled, settled);
    return await operation;
  }

  private async fencePendingLocalSenders(
    track?: PublicationTrack,
  ): Promise<void> {
    let shouldRetry: boolean;
    do {
      await this.waitForTrackOwnershipOperations();
      const pendingSenders = [...this.pendingLocalSenders].filter(
        ([, pending]) => track === undefined || pending.track === track,
      );
      const operations = new Set<Promise<void>>();
      for (const [sender, pending] of pendingSenders) {
        if (sender.track !== null) {
          operations.add(
            this.fenceLocalSender(pending.track, pending.generation, sender),
          );
        }
      }
      for (const registration of this.senderFenceOperations.values()) {
        if (track === undefined || registration.track === track) {
          operations.add(registration.operation);
        }
      }
      if (operations.size === 0) return;

      const results = await Promise.allSettled(operations);
      const failure = results.find(
        (result): result is PromiseRejectedResult =>
          result.status === "rejected",
      );
      if (failure) throw failure.reason;
      shouldRetry =
        [...this.pendingLocalSenders].some(
          ([sender, pending]) =>
            (track === undefined || pending.track === track) &&
            sender.track !== null,
        ) ||
        [...this.senderFenceOperations.values()].some(
          (registration) => track === undefined || registration.track === track,
        );
    } while (shouldRetry);
  }

  private forgetPendingLocalTrack(track: PublicationTrack): void {
    for (const [sender, pending] of this.pendingLocalSenders) {
      if (pending.track === track) this.pendingLocalSenders.delete(sender);
    }
    this.forgetPendingTrackSenderObservations(track);
  }

  private forgetPendingTrackSenderObservations(track: PublicationTrack): void {
    for (const [sender, pending] of this.pendingTrackSenderObservations) {
      if (pending.track === track) {
        this.pendingTrackSenderObservations.delete(sender);
      }
    }
  }

  private consumePendingTrackSenderObservations(track: PublicationTrack): void {
    const observations: Array<
      readonly [RTCRtpSender, PendingTrackSenderObservation]
    > = [];
    for (const [sender, pending] of this.pendingTrackSenderObservations) {
      if (pending.track !== track) continue;
      this.pendingTrackSenderObservations.delete(sender);
      observations.push([sender, pending]);
    }
    if (
      !this.ownsTrack(track) ||
      !this.trackOwner.canAcquireTrack(track) ||
      this.destroyed ||
      this.terminallyDisconnected
    ) {
      return;
    }
    for (const [sender, pending] of observations) {
      this.onTrackSenderDiscovered(track, sender, pending.expectedTrack);
    }
  }

  private onLocalTrackPublished(
    localTrackPublication: LocalTrackPublication,
  ): void {
    const track = localTrackPublication.track;
    const screenShareOperation = track
      ? getParticipantScreenShareOperation(
          this.connection.livekitRoom.localParticipant,
          track,
        )
      : undefined;
    if (
      screenShareOperation?.owner !== undefined &&
      screenShareOperation.owner !== this.trackOwner
    ) {
      this.publicationChanged$.next();
      return;
    }
    const staleScreenShare = screenShareOperation?.retired === true;
    if (this.destroyed || this.terminallyDisconnected || staleScreenShare) {
      if (track) {
        this.claimTrack(track, staleScreenShare || this.terminallyDisconnected);
        const generation = track.mediaStreamTrack;
        this.stopOwnedTrackGeneration(track, generation);
        if (!this.destroyed || staleScreenShare) {
          this.queueTrackReaper(
            track,
            generation,
            track.source ?? localTrackPublication.source,
          );
        }
      }
      if (this.destructionFinished) this.queueLateCleanup();
      this.publicationChanged$.next();
      return;
    }
    if (track) {
      this.markPublicationCommitted(track, track.mediaStreamTrack);
      this.claimTrack(track, true);
      if (!this.ownsTrack(track)) {
        this.publicationChanged$.next();
        return;
      }
      this.forgetPendingLocalTrack(track);
    }
    const trackUsable = track !== undefined && this.isTrackUsable(track);
    if (track && this.getResumablePublication(track.source)?.track === track) {
      this.clearSourceRecovery(track.source);
    }

    this.logger.info(
      `Local track published from source ${localTrackPublication.source}`,
    );
    if (track) {
      const generation = track.mediaStreamTrack;
      const healthyPublication =
        this.getControlledPausedPublication(track.source) ??
        this.getHealthyPublication(track.source);
      const isPreferredTrack =
        healthyPublication?.track === track &&
        track.mediaStreamTrack === generation;
      if (!trackUsable || !isPreferredTrack) {
        void this.ownMediaOperation(
          this.pauseTrackGenerationsFailClosed([{ track, generation }]),
        ).catch(() => {
          this.logger.error("Failed to pause duplicate local media");
        });
        this.queueTrackReaper(track, generation);
      } else if (!this.isPublishingIntentCurrent()) {
        void this.ownMediaOperation(
          this.pauseTrackGenerationsFailClosed([{ track, generation }]),
        ).catch(() => {
          this.logger.error("Failed to pause upstreams");
        });
      } else {
        this.requestPublishingReconciliation();
      }
    }
    // also check the mute state and apply it
    if (localTrackPublication.source === Track.Source.Microphone) {
      void this.queueSourceReconciliation(Track.Source.Microphone);
    } else if (localTrackPublication.source === Track.Source.Camera) {
      void this.queueSourceReconciliation(Track.Source.Camera);
    }
    if (track) this.reapSourcePublications(track.source);
    this.publicationChanged$.next();
  }

  private onLocalTrackUnpublished(
    localTrackPublication: LocalTrackPublication,
  ): void {
    const track = localTrackPublication.track;
    const source = track?.source ?? localTrackPublication.source;
    if (track) {
      this.clearPublicationCommitted(track, track.mediaStreamTrack);
      const preferredTrack = this.preferredSourceTracks.get(source);
      if (
        preferredTrack?.track === track &&
        !this.getSourcePublications(source).some(
          (publication) => publication.track === track,
        )
      ) {
        this.preferredSourceTracks.delete(source);
      }
      this.releaseStoppedUnpublishedTrack(track);
    }
    if (!this.getResumablePublication(source)) {
      this.sourceLossGenerations.set(
        source,
        (this.sourceLossGenerations.get(source) ?? 0) + 1,
      );
      this.clearSourceRecovery(source);
    }
    this.publicationChanged$.next();
    if (
      (source === Track.Source.Microphone || source === Track.Source.Camera) &&
      this.getDesiredSourceEnabled(source)
    ) {
      this.scheduleSourceRecovery(source);
    }
    if (this.isPublishingIntentCurrent()) {
      this.requestPublishingReconciliation();
    }
  }

  /**
   * Create and setup local audio and video tracks based on the current mute states.
   * It creates the tracks only if audio and/or video is enabled, to avoid unnecessary
   * permission prompts.
   *
   * It also observes mute state changes to update LiveKit microphone/camera states accordingly.
   * If a track is not created initially because disabled, it will be created when unmuting.
   *
   * This call is not blocking anymore, instead callers can listen to the
   * `RoomEvent.MediaDevicesError` event in the LiveKit room to be notified of any errors.
   *
   */
  public async createAndSetupTracks(): Promise<void> {
    this.logger.debug("createAndSetupTracks called");
    if (this.destroyed || this.terminallyDisconnected || this.setupStarted)
      return;

    const lkRoom = this.connection.livekitRoom;
    // Check if audio and/or video is enabled. We only create tracks if enabled,
    // because it could prompt for permission, and we don't want to do that unnecessarily.
    const audio = this.muteStates.audio.enabled$.value;
    const video = this.muteStates.video.enabled$.value;
    this.desiredSourceEnabled.set(Track.Source.Microphone, audio);
    this.desiredSourceEnabled.set(Track.Source.Camera, video);
    this.setupStarted = true;
    this.publicationChanged$.next();

    // Observe mute state changes and update LiveKit microphone/camera states accordingly
    this.observeMuteStates();

    // We don't await the creation because LiveKit can block until the tracks are
    // fully published, not only until they are created.
    // We are using the `ParticipantEvent.LocalTrackPublished` to be notified
    // when tracks are actually published, and at that point
    // we can pause upstream if needed (depending on if startPublishing has been called).
    const requestedSources = this.getRequestedSources(audio, video).filter(
      (source) =>
        !this.hasResumablePublication(source) || !this.isSourceEnabled(source),
    );
    this.initialPublicationPending = true;
    this.startPublicationAttempt("initial", requestedSources, lkRoom);

    return Promise.resolve();
  }

  private startPublicationAttempt(
    attempt: PublicationAttempt,
    sources: Track.Source[],
    lkRoom: LivekitRoom,
  ): void {
    void this.registerSourceEnableOperation(
      sources,
      this.enableSources(sources, lkRoom, attempt === "initial"),
    )
      .then(
        () => this.onPublicationAttemptSettled(attempt, sources, "fulfilled"),
        (error: unknown) =>
          this.onPublicationAttemptSettled(attempt, sources, "rejected", error),
      )
      .catch(() => {
        this.logger.error("Failed to process local media publication result");
      });
  }

  private async enableSources(
    sources: Track.Source[],
    lkRoom: LivekitRoom,
    preferCombinedCapture: boolean,
  ): Promise<void> {
    const microphoneRequested = sources.includes(Track.Source.Microphone);
    const cameraRequested = sources.includes(Track.Source.Camera);

    if (preferCombinedCapture && microphoneRequested && cameraRequested) {
      try {
        await this.createAndPublishCameraAndMicrophone(lkRoom);
        return;
      } catch (error) {
        if (!(error instanceof CombinedCaptureFailure)) throw error;
        if (this.destroyed || this.terminallyDisconnected) throw error.cause;
      }
    }

    const failures: SourcePublicationFailure[] = [];
    for (const source of sources) {
      if (
        !this.getDesiredSourceEnabled(source) ||
        (this.hasResumablePublication(source) && this.isSourceEnabled(source))
      ) {
        continue;
      }
      try {
        await this.enableParticipantSource(source, lkRoom);
      } catch (error) {
        failures.push({ source, error });
      }
    }
    if (failures.length > 0) {
      throw new SourcePublicationFailures(failures);
    }
  }

  private async createAndPublishCameraAndMicrophone(
    lkRoom: LivekitRoom,
  ): Promise<void> {
    // Create both tracks at once to preserve a single browser permission prompt.
    let tracks;
    try {
      tracks = await lkRoom.localParticipant.createTracks({
        audio: true,
        video: true,
      });
    } catch (error) {
      throw new CombinedCaptureFailure(error);
    }
    tracks.forEach((track) => this.claimTrack(track));
    if (this.destroyed || this.terminallyDisconnected) {
      tracks.forEach((track) =>
        this.stopAndReleaseOwnedUnpublishedTrack(track),
      );
      return;
    }

    const requestedSources = new Set(this.getRequestedSources());
    const publicationResults = await Promise.allSettled(
      tracks.map(async (track) => {
        if (!requestedSources.has(track.source)) {
          this.stopAndReleaseOwnedUnpublishedTrack(track);
          return;
        }
        const existingPublication = this.getResumablePublication(track.source);
        if (existingPublication) {
          this.claimPublication(existingPublication, true);
          this.stopAndReleaseOwnedUnpublishedTrack(track);
          return;
        }
        try {
          await lkRoom.localParticipant.publishTrack(track);
          this.forgetPendingLocalTrack(track);
        } catch (error) {
          let senderFenceFailure: unknown;
          try {
            await this.fencePendingLocalSenders(track);
          } catch (fenceError) {
            senderFenceFailure = fenceError;
          }
          this.stopAndReleaseOwnedUnpublishedTrack(track);
          throw senderFenceFailure ?? error;
        }
      }),
    );
    publicationResults.forEach((result, index) => {
      if (result.status === "rejected") {
        this.stopAndReleaseOwnedUnpublishedTrack(tracks[index]);
      }
    });
    const failures = publicationResults.flatMap((result, index) =>
      result.status === "rejected"
        ? [{ source: tracks[index].source, error: result.reason }]
        : [],
    );
    if (failures.length > 0) throw new SourcePublicationFailures(failures);
  }

  private onPublicationAttemptSettled(
    attempt: PublicationAttempt,
    attemptedSources: Track.Source[],
    outcome: "fulfilled" | "rejected",
    error?: unknown,
  ): void {
    if (attempt === "initial") this.initialPublicationPending = false;
    this.publicationChanged$.next();

    if (this.destroyed || this.terminallyDisconnected) return;

    const requestedSources = this.getRequestedSources();
    const publishedSourceCount = requestedSources.filter((source) =>
      this.hasResumablePublication(source),
    ).length;
    const diagnostics = {
      attempt,
      requestedSourceCount: requestedSources.length,
      publishedSourceCount,
      missingSourceCount: requestedSources.length - publishedSourceCount,
    };

    if (outcome === "rejected") {
      const failures =
        error instanceof SourcePublicationFailures
          ? error.failures
          : attemptedSources.map((source) => ({ source, error }));
      if (attempt === "initial") {
        for (const failure of failures) {
          if (
            terminalPublicationFailures.has(
              classifyPublicationFailure(failure.error),
            )
          ) {
            this.automaticRecoveryBlockedSources.add(failure.source);
          }
        }
      }
      const failureCategory = classifyPublicationFailure(
        selectPublicationFailure(failures),
      );
      this.logger.warn("Local media publication attempt failed", {
        attempt: diagnostics.attempt,
        failureCategory,
        requestedSourceCount: diagnostics.requestedSourceCount,
        publishedSourceCount: diagnostics.publishedSourceCount,
        missingSourceCount: diagnostics.missingSourceCount,
      });
    } else if (diagnostics.missingSourceCount > 0) {
      this.logger.warn("Local media publication attempt incomplete", {
        attempt: diagnostics.attempt,
        requestedSourceCount: diagnostics.requestedSourceCount,
        publishedSourceCount: diagnostics.publishedSourceCount,
        missingSourceCount: diagnostics.missingSourceCount,
      });
    }

    for (const source of attemptedSources) {
      if (this.getResumablePublication(source)) {
        this.clearSourceRecovery(source);
      } else {
        this.scheduleSourceRecovery(source);
      }
    }
    if (this.isPublishingIntentCurrent()) {
      this.requestPublishingReconciliation();
    }
  }

  private cancelSourceRecoveryTimer(source: Track.Source): void {
    const recoveryTimer = this.recoveryTimers.get(source);
    if (!recoveryTimer) return;
    clearTimeout(recoveryTimer.timeout);
    this.recoveryTimers.delete(source);
  }

  private cancelSourceRecoveryTimers(): void {
    for (const source of this.recoveryTimers.keys()) {
      this.cancelSourceRecoveryTimer(source);
    }
  }

  private clearSourceRecovery(source: Track.Source): void {
    this.cancelSourceRecoveryTimer(source);
    this.recoveryStates.delete(source);
  }

  private scheduleSourceRecovery(source: Track.Source): void {
    if (
      (source !== Track.Source.Microphone && source !== Track.Source.Camera) ||
      this.destroyed ||
      this.terminallyDisconnected ||
      !this.setupStarted ||
      this.initialPublicationPending ||
      !this.getDesiredSourceEnabled(source) ||
      this.getResumablePublication(source) ||
      this.sourceEnableOperations.has(source) ||
      this.automaticRecoveryBlockedSources.has(source) ||
      this.connection.livekitRoom.state !== LivekitConnectionState.Connected
    ) {
      return;
    }

    const lossGeneration = this.sourceLossGenerations.get(source) ?? 0;
    const existingTimer = this.recoveryTimers.get(source);
    if (existingTimer?.lossGeneration === lossGeneration) return;
    if (existingTimer) this.cancelSourceRecoveryTimer(source);

    const recoveryState = this.recoveryStates.get(source);
    const attempts =
      recoveryState?.lossGeneration === lossGeneration
        ? recoveryState.attempts
        : 0;
    if (attempts >= maximumAutomaticRecoveryAttempts) return;

    const delay = automaticRecoveryBaseDelayMs * 2 ** attempts;
    const recoveryTimer: SourceRecoveryTimer = {
      lossGeneration,
      timeout: setTimeout(() => {
        if (this.recoveryTimers.get(source) !== recoveryTimer) return;
        this.recoveryTimers.delete(source);
        if (
          this.destroyed ||
          this.terminallyDisconnected ||
          (this.sourceLossGenerations.get(source) ?? 0) !== lossGeneration ||
          !this.getDesiredSourceEnabled(source)
        ) {
          return;
        }
        this.recoverMissingRequestedSources([source]);
      }, delay),
    };
    this.recoveryTimers.set(source, recoveryTimer);
  }

  private recoverMissingRequestedSources(
    requestedSources = this.getRequestedSources(),
  ): void {
    if (
      this.destroyed ||
      this.terminallyDisconnected ||
      !this.setupStarted ||
      this.initialPublicationPending
    ) {
      return;
    }

    if (
      this.connection.livekitRoom.state !== LivekitConnectionState.Connected
    ) {
      return;
    }
    const missingSources = requestedSources.filter((source) => {
      const lossGeneration = this.sourceLossGenerations.get(source) ?? 0;
      const recoveryState = this.recoveryStates.get(source);
      const attempts =
        recoveryState?.lossGeneration === lossGeneration
          ? recoveryState.attempts
          : 0;
      return (
        this.getDesiredSourceEnabled(source) &&
        !this.getResumablePublication(source) &&
        !this.sourceEnableOperations.has(source) &&
        !this.automaticRecoveryBlockedSources.has(source) &&
        attempts < maximumAutomaticRecoveryAttempts
      );
    });
    if (missingSources.length === 0) return;

    missingSources.forEach((source) => {
      this.cancelSourceRecoveryTimer(source);
      const lossGeneration = this.sourceLossGenerations.get(source) ?? 0;
      const recoveryState = this.recoveryStates.get(source);
      if (recoveryState?.lossGeneration === lossGeneration) {
        recoveryState.attempts += 1;
      } else {
        this.recoveryStates.set(source, { lossGeneration, attempts: 1 });
      }
    });
    this.startPublicationAttempt(
      "recovery",
      missingSources,
      this.connection.livekitRoom,
    );
  }

  private getRequestedSources(
    audio = this.muteStates.audio.enabled$.value,
    video = this.muteStates.video.enabled$.value,
  ): Track.Source[] {
    if (this.setupStarted) {
      audio = this.getDesiredSourceEnabled(Track.Source.Microphone);
      video = this.getDesiredSourceEnabled(Track.Source.Camera);
    }
    const sources: Track.Source[] = [];
    if (audio) sources.push(Track.Source.Microphone);
    if (video) sources.push(Track.Source.Camera);
    return sources;
  }

  private hasPublication(source: Track.Source): boolean {
    const preferredPublication = this.isPublishingIntentCurrent()
      ? this.getHealthyPublication(source)
      : this.getResumablePublication(source);
    if (!preferredPublication?.track) return false;
    const preferredTrack = preferredPublication.track;
    const preferredGeneration = preferredTrack.mediaStreamTrack;
    return this.getSafetySourceTracks(source).every(
      (track) =>
        (track === preferredTrack &&
          track.mediaStreamTrack === preferredGeneration) ||
        this.isTrackNotSending(track),
    );
  }

  private hasResumablePublication(source: Track.Source): boolean {
    const publication = this.getResumablePublication(source);
    if (!publication?.track) return false;
    const track = publication.track;
    const generation = track.mediaStreamTrack;
    return this.getSafetySourceTracks(source).every(
      (candidate) =>
        (candidate === track && candidate.mediaStreamTrack === generation) ||
        this.isTrackNotSending(candidate),
    );
  }

  private hasUncontrolledPublications(): boolean {
    if (
      [...this.pendingTrackSenderObservations].some(
        ([sender]) => sender.track !== null,
      )
    ) {
      return true;
    }
    for (const source of [
      Track.Source.Microphone,
      Track.Source.Camera,
      Track.Source.ScreenShare,
      Track.Source.ScreenShareAudio,
    ]) {
      const healthyTrack = this.getHealthyPublication(source)?.track;
      if (
        this.isPublishingIntentCurrent() &&
        this.getResumablePublication(source)?.track &&
        !healthyTrack
      ) {
        return true;
      }
      if (
        this.getSafetySourceTracks(source).some(
          (track) =>
            (this.isTrackGenerationLive(track) ||
              !this.isTrackNotSending(track)) &&
            (healthyTrack
              ? track !== healthyTrack
              : !this.isTrackNotSending(track)),
        )
      ) {
        return true;
      }
    }
    return false;
  }

  private getHealthyPublication(
    source: Track.Source,
  ): LocalTrackPublication | undefined {
    const publications = this.getSourcePublications(source);
    const preferredTrack = this.preferredSourceTracks.get(source);
    if (
      preferredTrack &&
      this.isControlledPausedGeneration(
        preferredTrack.track,
        preferredTrack.generation,
      ) &&
      publications.some(
        ({ track }) =>
          track === preferredTrack.track &&
          track.mediaStreamTrack === preferredTrack.generation &&
          this.isTrackResumable(track),
      )
    ) {
      return undefined;
    }
    const preferredPublication = publications.find((publication) => {
      const track = publication.track;
      return (
        track !== undefined &&
        preferredTrack !== undefined &&
        track === preferredTrack.track &&
        track.mediaStreamTrack === preferredTrack.generation &&
        this.isTrackHealthy(track)
      );
    });
    if (preferredPublication) return preferredPublication;

    const publication = publications.find(
      (candidate) =>
        candidate.track !== undefined && this.isTrackHealthy(candidate.track),
    );
    if (publication?.track) {
      this.preferredSourceTracks.set(source, {
        track: publication.track,
        generation: publication.track.mediaStreamTrack,
      });
    } else if (
      preferredTrack &&
      !publications.some(
        ({ track }) =>
          track === preferredTrack.track &&
          track.mediaStreamTrack === preferredTrack.generation &&
          this.isTrackResumable(track),
      )
    ) {
      this.preferredSourceTracks.delete(source);
    }
    return publication;
  }

  private getResumablePublication(
    source: Track.Source,
  ): LocalTrackPublication | undefined {
    const publications = this.getSourcePublications(source);
    const preferredTrack = this.preferredSourceTracks.get(source);
    const preferredPublication = publications.find((publication) => {
      const track = publication.track;
      return (
        track !== undefined &&
        preferredTrack !== undefined &&
        track === preferredTrack.track &&
        track.mediaStreamTrack === preferredTrack.generation &&
        this.isTrackResumable(track)
      );
    });
    if (preferredPublication) return preferredPublication;

    const publication = publications.find(
      (candidate) =>
        candidate.track !== undefined && this.isTrackResumable(candidate.track),
    );
    if (publication?.track) {
      this.preferredSourceTracks.set(source, {
        track: publication.track,
        generation: publication.track.mediaStreamTrack,
      });
    }
    return publication;
  }

  private getControlledPausedPublication(
    source: Track.Source,
  ): LocalTrackPublication | undefined {
    const preferredTrack = this.preferredSourceTracks.get(source);
    if (!preferredTrack) return undefined;
    return this.getSourcePublications(source).find(
      ({ track }) =>
        track === preferredTrack.track &&
        track.mediaStreamTrack === preferredTrack.generation &&
        this.isControlledPausedGeneration(track, preferredTrack.generation) &&
        this.isTrackResumable(track),
    );
  }

  private getUsablePublication(
    source: Track.Source,
  ): LocalTrackPublication | undefined {
    const publications = this.getSourcePublications(source);
    const preferredTrack = this.preferredSourceTracks.get(source);
    return (
      publications.find((publication) => {
        const track = publication.track;
        return (
          track !== undefined &&
          preferredTrack !== undefined &&
          track === preferredTrack.track &&
          track.mediaStreamTrack === preferredTrack.generation &&
          this.isTrackUsable(track)
        );
      }) ??
      publications.find(
        (publication) =>
          publication.track !== undefined &&
          this.isTrackUsable(publication.track),
      )
    );
  }

  private getDesiredSourceEnabled(source: Track.Source): boolean {
    if (!this.setupStarted) {
      if (source === Track.Source.Microphone) {
        return this.muteStates.audio.enabled$.value;
      }
      if (source === Track.Source.Camera) {
        return this.muteStates.video.enabled$.value;
      }
    }
    return (
      this.desiredSourceEnabled.get(source) ??
      (source === Track.Source.Microphone
        ? this.muteStates.audio.enabled$.value
        : this.muteStates.video.enabled$.value)
    );
  }

  private setDesiredSourceEnabled(
    source: Track.Source,
    enabled: boolean,
  ): void {
    const wasEnabled = this.getDesiredSourceEnabled(source);
    this.desiredSourceEnabled.set(source, enabled);
    if (enabled && !wasEnabled) {
      this.automaticRecoveryBlockedSources.delete(source);
      this.clearSourceRecovery(source);
    }
    if (!enabled) {
      this.clearSourceRecovery(source);
      this.stopOwnedUnpublishedTracks(source, true);
    }
    this.publicationChanged$.next();
  }

  private setPublishingActive(active: boolean): void {
    if (this.publishingActiveSubject$.value !== active) {
      this.publishingActiveSubject$.next(active);
    }
  }

  private cancelPublishingIntent(): void {
    this.publishingRequested = false;
    ++this.publishingControlGeneration;
    this.publicationChanged$.next();
  }

  private ensureTrackPaused(track: PublicationTrack): void {
    if (this.startingTrackControlOperations.has(track)) {
      queueMicrotask(() => this.ensureTrackPaused(track));
      return;
    }
    const existingOperation = this.trackControlOperations.get(track);
    if (existingOperation) {
      const retry = (): void => {
        if (
          !this.isPublishingIntentCurrent() &&
          !this.isTrackNotSending(track)
        ) {
          this.ensureTrackPaused(track);
        }
      };
      void existingOperation.then(retry, retry);
      return;
    }
    if (
      !this.ownsTrack(track) ||
      (!this.isTrackGenerationLive(track) && this.isTrackNotSending(track))
    ) {
      return;
    }
    this.startingTrackControlOperations.add(track);
    const operation = this.ownMediaOperation(
      this.pauseTrackGenerationsFailClosed([
        this.snapshotTrackGeneration(track),
      ]),
    );
    this.startingTrackControlOperations.delete(track);
    this.trackControlOperations.set(track, operation);
    const settled = (): void => {
      if (this.trackControlOperations.get(track) === operation) {
        this.trackControlOperations.delete(track);
      }
      this.publicationChanged$.next();
      if (this.isPublishingIntentCurrent()) {
        this.requestPublishingReconciliation();
      } else if (
        this.areSourcesNotSending([
          Track.Source.Microphone,
          Track.Source.Camera,
          Track.Source.ScreenShare,
          Track.Source.ScreenShareAudio,
        ])
      ) {
        this.setPublishingActive(false);
      }
    };
    void operation.then(settled, () => {
      this.logger.error("Failed to pause restored local media");
      settled();
    });
  }

  private reconcileOwnedTrackControls(): void {
    for (const track of this.ownedTracks) this.observeTrackState(track);
    if (this.destroyed || this.terminallyDisconnected) {
      this.forceStopKnownTracks();
      return;
    }
    if (this.isPublishingIntentCurrent()) {
      this.requestPublishingReconciliation();
      return;
    }
    for (const track of this.getPublishedTracks()) {
      if (this.ownsTrack(track)) this.ensureTrackPaused(track);
    }
  }

  private requestPublishingReconciliation(): void {
    if (
      this.publishingReconciliationQueued ||
      !this.isPublishingIntentCurrent()
    ) {
      return;
    }
    this.publishingReconciliationQueued = true;
    queueMicrotask(() => {
      this.publishingReconciliationQueued = false;
      if (!this.isPublishingIntentCurrent() || this.startPublishingOperation) {
        return;
      }
      const operation = this.runPublishingReconciliation(
        this.publishingControlGeneration,
      );
      void operation.catch(() => {
        this.logger.error("Failed to reconcile requested local media");
      });
    });
  }

  private async ownMediaOperation<T>(
    operation: Promise<T>,
    trackGenerationsMayChange = false,
  ): Promise<T> {
    const normalizedOperation = Promise.resolve(operation);
    const settled = normalizedOperation.then(
      () => undefined,
      () => undefined,
    );
    this.mediaOperations.add(settled);
    void settled.then(() => {
      this.mediaOperations.delete(settled);
      if (trackGenerationsMayChange) this.publicationChanged$.next();
      if (this.destroyed) {
        this.claimPublishedTracksForDestruction();
        this.forceStopKnownTracks();
        if (this.destructionFinished) this.queueLateCleanup();
      } else if (this.terminallyDisconnected) {
        for (const track of this.getPublishedTracks()) {
          this.claimTrack(track, true);
          const generation = track.mediaStreamTrack;
          this.stopOwnedTrackGeneration(track, generation);
          this.queueTrackReaper(track, generation);
        }
      } else {
        if (trackGenerationsMayChange) {
          this.reconcileOwnedTrackControls();
        }
        this.releaseStoppedUnpublishedTracks();
      }
    });
    return await normalizedOperation;
  }

  /** Registers a LiveKit media mutation that may publish after destruction. */
  public async registerMediaOperation<T>(operation: Promise<T>): Promise<T> {
    return await this.ownMediaOperation(operation, true);
  }

  private async registerTrackGenerationOperation<T>(
    operationFactory: () => Promise<T>,
    trackGenerations: readonly PublicationTrackGeneration[],
    controlGeneration: number,
  ): Promise<T> {
    const tracks = [...new Set(trackGenerations.map(({ track }) => track))];
    tracks.forEach((track) => this.beginTrackMutationOperation(track));
    try {
      return await this.ownMediaOperation(operationFactory());
    } finally {
      tracks.forEach((track) => this.endTrackMutationOperation(track));
      this.publicationChanged$.next();
      for (const { track, generation } of trackGenerations) {
        if (
          this.destroyed ||
          this.terminallyDisconnected ||
          !this.ownsTrack(track)
        ) {
          getPublicationTrackGenerationState(track, generation).unsafeMutation =
            true;
          getPublicationTrackGenerationState(
            track,
            track.mediaStreamTrack,
          ).unsafeMutation = true;
          publicationTrackOwners
            .get(track)
            ?.cleanupLateTrackMutation(track, generation);
          continue;
        }
        this.observeTrackState(track);
        this.reapSourcePublications(track.source);
        if (
          controlGeneration === this.publishingControlGeneration &&
          this.isPublishingIntentCurrent()
        ) {
          this.requestPublishingReconciliation();
        } else {
          this.ensureTrackPaused(track);
        }
      }
    }
  }

  private async ownTrackMutationOperation<T>(
    track: PublicationTrack,
    generation: MediaStreamTrack,
    mutation: (markMutationStarted: () => void) => Promise<T>,
  ): Promise<T> {
    let mutationStarted = false;
    const controlGeneration = this.publishingControlGeneration;
    this.beginTrackMutationOperation(track);
    const operation = Promise.resolve().then(
      async () =>
        await mutation(() => {
          mutationStarted = true;
        }),
    );
    try {
      return await this.ownMediaOperation(operation, true);
    } finally {
      this.endTrackMutationOperation(track);
      if (
        mutationStarted &&
        (this.destroyed ||
          this.terminallyDisconnected ||
          !this.ownsTrack(track))
      ) {
        getPublicationTrackGenerationState(track, generation).unsafeMutation =
          true;
        getPublicationTrackGenerationState(
          track,
          track.mediaStreamTrack,
        ).unsafeMutation = true;
        publicationTrackOwners
          .get(track)
          ?.cleanupLateTrackMutation(track, generation);
      } else if (mutationStarted) {
        this.observeTrackState(track);
        this.reapSourcePublications(track.source);
        if (
          controlGeneration === this.publishingControlGeneration &&
          this.isPublishingIntentCurrent()
        ) {
          this.requestPublishingReconciliation();
        } else {
          this.ensureTrackPaused(track);
        }
      }
    }
  }

  private beginTrackMutationOperation(track: PublicationTrack): void {
    this.trackMutationOperationCounts.set(
      track,
      (this.trackMutationOperationCounts.get(track) ?? 0) + 1,
    );
  }

  private endTrackMutationOperation(track: PublicationTrack): void {
    const remaining = (this.trackMutationOperationCounts.get(track) ?? 1) - 1;
    if (remaining > 0) this.trackMutationOperationCounts.set(track, remaining);
    else this.trackMutationOperationCounts.delete(track);
  }

  private hasPendingTrackMutationOperation(track: PublicationTrack): boolean {
    return (this.trackMutationOperationCounts.get(track) ?? 0) > 0;
  }

  /** Starts a screen-share mutation owned by this connection generation. */
  public async setScreenShareEnabled(
    enabled: boolean,
    options?: ScreenShareCaptureOptions,
  ): Promise<void> {
    if (this.destroyed || this.terminallyDisconnected) {
      throw new Error("Cannot change screen sharing on a destroyed Publisher");
    }
    const participant = this.connection.livekitRoom.localParticipant;
    const activeOperations = [...this.screenShareOperations];
    const screenShareOperation = this.createScreenShareOperation(!enabled);
    this.registerScreenShareOperation(participant, screenShareOperation);
    try {
      await this.ownMediaOperation(
        enabled
          ? this.publishScreenShareTracks(screenShareOperation, options)
          : this.disableScreenShareTracks(
              screenShareOperation,
              activeOperations,
            ),
        true,
      );
    } finally {
      this.finishScreenShareOperation(participant, screenShareOperation);
    }
  }

  private createScreenShareOperation(retired: boolean): ScreenShareOperation {
    let settle = (): void => undefined;
    const settled = new Promise<void>((resolve) => {
      settle = resolve;
    });
    return {
      owner: this.trackOwner,
      tracks: new Set(),
      senderFenceOperations: new Set(),
      settled,
      settle,
      retired,
    };
  }

  private registerScreenShareOperation(
    participant: LocalParticipant,
    operation: ScreenShareOperation,
  ): void {
    let operations = participantScreenShareOperations.get(participant);
    if (!operations) {
      operations = new Set();
      participantScreenShareOperations.set(participant, operations);
    }
    operations.add(operation);
    this.screenShareOperations.add(operation);
  }

  private finishScreenShareOperation(
    participant: LocalParticipant,
    operation: ScreenShareOperation,
  ): void {
    this.screenShareOperations.delete(operation);
    const operations = participantScreenShareOperations.get(participant);
    operations?.delete(operation);
    if (operations?.size === 0) {
      participantScreenShareOperations.delete(participant);
    }
    operation.settle();
  }

  private async publishScreenShareTracks(
    operation: ScreenShareOperation,
    options?: ScreenShareCaptureOptions,
  ): Promise<void> {
    const participant = this.connection.livekitRoom.localParticipant;
    const senderCreatedHandler = (sender: RTCRtpSender, track: Track): void => {
      const operationTrack = [...operation.tracks].find(
        (candidate) => candidate === track,
      );
      if (
        !operationTrack ||
        (!operation.retired && !this.destroyed && !this.terminallyDisconnected)
      ) {
        return;
      }
      this.stopOwnedTrackGeneration(
        operationTrack,
        operationTrack.mediaStreamTrack,
      );
      this.queueScreenShareSenderFence(operation, operationTrack, sender);
    };
    participant.on(ParticipantEvent.LocalSenderCreated, senderCreatedHandler);
    try {
      const tracks = await participant.createScreenTracks({ ...options });
      for (const track of tracks) {
        operation.tracks.add(track);
        this.claimTrack(track);
      }
      if (operation.retired || this.destroyed || this.terminallyDisconnected) {
        operation.retired = true;
        await this.fenceScreenShareTracks(operation);
        return;
      }

      const publicationResults = await Promise.allSettled(
        tracks.map(async (track) => await participant.publishTrack(track)),
      );
      const failedPublication = publicationResults.find(
        (result) => result.status === "rejected",
      );
      if (failedPublication) operation.retired = true;

      if (operation.retired || this.destroyed || this.terminallyDisconnected) {
        operation.retired = true;
        await this.fenceScreenShareTracks(operation);
      } else {
        for (const result of publicationResults) {
          if (result.status === "fulfilled")
            this.claimPublication(result.value);
        }
      }

      if (failedPublication?.status === "rejected") {
        throw failedPublication.reason;
      }
    } finally {
      participant.off(
        ParticipantEvent.LocalSenderCreated,
        senderCreatedHandler,
      );
      await Promise.allSettled([...operation.senderFenceOperations]);
    }
  }

  private async disableScreenShareTracks(
    operation: ScreenShareOperation,
    activeOperations: ScreenShareOperation[],
  ): Promise<void> {
    for (const activeOperation of activeOperations) {
      this.retireScreenShareOperation(activeOperation);
    }
    for (const source of [
      Track.Source.ScreenShare,
      Track.Source.ScreenShareAudio,
    ]) {
      for (const track of this.getSourceTracks(source)) {
        if (!this.ownsTrack(track)) continue;
        operation.tracks.add(track);
      }
    }

    const cleanupResults = await Promise.allSettled([
      this.fenceScreenShareTracks(operation),
      ...activeOperations.map(async ({ settled }) => await settled),
    ]);
    const failedCleanup = cleanupResults.find(
      (result) => result.status === "rejected",
    );
    if (failedCleanup?.status === "rejected") throw failedCleanup.reason;
  }

  private queueScreenShareSenderFence(
    operation: ScreenShareOperation,
    track: PublicationTrack,
    sender: RTCRtpSender,
  ): void {
    const generation = track.mediaStreamTrack;
    const fence = this.quarantineTrackGeneration({
      track,
      generation,
      senderBindings: [
        {
          sender,
          expectedTrack: generation,
          current: true,
        },
      ],
    }).catch(() => {
      this.logger.error("Failed to fence an exact screen-share sender");
    });
    operation.senderFenceOperations.add(fence);
    void fence.finally(() => operation.senderFenceOperations.delete(fence));
  }

  private async fenceScreenShareTracks(
    operation: ScreenShareOperation,
  ): Promise<void> {
    await Promise.all(
      [...operation.tracks].map(
        async (track) =>
          await this.quarantineTrackGeneration(
            this.snapshotTrackGeneration(track),
          ),
      ),
    );
  }

  private retireScreenShareOperation(operation: ScreenShareOperation): void {
    if (operation.retired) return;
    operation.retired = true;
    const fence = this.fenceScreenShareTracks(operation).catch(() => {
      this.logger.error("Failed to retire exact screen-share tracks");
    });
    operation.senderFenceOperations.add(fence);
    void fence.finally(() => operation.senderFenceOperations.delete(fence));
  }

  private retireScreenShareOperations(): void {
    for (const operation of this.screenShareOperations) {
      this.retireScreenShareOperation(operation);
    }
  }

  private async registerSourceEnableOperation<T>(
    sources: Track.Source[],
    operation: Promise<T>,
  ): Promise<T> {
    const ownedOperation = this.ownMediaOperation(operation, true);
    const settled = ownedOperation.then(
      () => undefined,
      () => undefined,
    );

    for (const source of sources) {
      let sourceOperations = this.sourceEnableOperations.get(source);
      if (!sourceOperations) {
        sourceOperations = new Set();
        this.sourceEnableOperations.set(source, sourceOperations);
      }
      sourceOperations.add(settled);
    }

    void settled.then(() => {
      for (const source of sources) {
        const sourceOperations = this.sourceEnableOperations.get(source);
        sourceOperations?.delete(settled);
        if (sourceOperations?.size === 0) {
          this.sourceEnableOperations.delete(source);
        }
      }
    });
    return await ownedOperation;
  }

  private async waitForSourceEnableOperations(
    source: Track.Source,
  ): Promise<void> {
    let operations = this.sourceEnableOperations.get(source);
    while (operations && operations.size > 0) {
      await Promise.all([...operations]);
      operations = this.sourceEnableOperations.get(source);
    }
  }

  private async waitForTrackOwnershipOperations(): Promise<void> {
    while (this.trackOwnershipOperations.size > 0) {
      await Promise.all([...this.trackOwnershipOperations]);
    }
  }

  private async queueSourceReconciliation(
    source: Track.Source,
  ): Promise<boolean> {
    const previous =
      this.sourceReconciliationTails.get(source) ?? Promise.resolve();
    const reconciliation = previous.then(async () => {
      return await this.reconcileSourceState(source);
    });
    const tail = reconciliation.then(
      () => undefined,
      () => undefined,
    );
    this.sourceReconciliationTails.set(source, tail);
    void tail.then(() => {
      if (this.sourceReconciliationTails.get(source) === tail) {
        this.sourceReconciliationTails.delete(source);
      }
    });
    return await this.ownMediaOperation(reconciliation);
  }

  private async reconcileSourceState(source: Track.Source): Promise<boolean> {
    while (!this.destroyed && !this.terminallyDisconnected) {
      const desired = this.getDesiredSourceEnabled(source);
      if (
        desired &&
        !this.hasResumablePublication(source) &&
        this.sourceEnableOperations.has(source)
      ) {
        await this.waitForSourceEnableOperations(source);
        if (this.destroyed || this.terminallyDisconnected) break;
        if (desired !== this.getDesiredSourceEnabled(source)) continue;
      }

      const enablePending = this.sourceEnableOperations.has(source);
      if (!desired && enablePending && !this.hasResumablePublication(source)) {
        return false;
      }
      const enabled = this.isSourceEnabled(source);
      const needsUpdate =
        enabled !== desired ||
        (desired && !this.hasResumablePublication(source)) ||
        (!desired && enablePending);

      if (needsUpdate) {
        try {
          this.logger.debug(
            `handler: Setting LiveKit ${source} enabled: ${desired}`,
          );
          await this.setSourceEnabled(source, desired);
        } catch (error) {
          if (
            terminalPublicationFailures.has(classifyPublicationFailure(error))
          ) {
            this.automaticRecoveryBlockedSources.add(source);
          }
          this.logSourceUpdateFailure(source);
          return this.isSourceEnabled(source);
        }
        if (this.destroyed || this.terminallyDisconnected) break;
      }

      if (
        !this.isPublishingIntentCurrent() &&
        desired &&
        this.hasResumablePublication(source)
      ) {
        try {
          await this.pauseUpstreams(this.connection.livekitRoom, [source]);
        } catch {
          this.logSourceUpdateFailure(source);
        }
      }

      const reconciled = this.isSourceEnabled(source);
      if (desired === this.getDesiredSourceEnabled(source)) return reconciled;
    }
    return this.isSourceEnabled(source);
  }

  private async setSourceEnabled(
    source: Track.Source,
    enabled: boolean,
  ): Promise<void> {
    const localParticipant = this.connection.livekitRoom.localParticipant;
    if (enabled) {
      await this.registerSourceEnableOperation(
        [source],
        this.enableParticipantSource(source, this.connection.livekitRoom),
      );
    } else {
      const tracks = this.getSourceTracks(source).filter((track) =>
        this.isTrackGenerationLive(track),
      );
      const operation =
        tracks.length > 0
          ? Promise.all(tracks.map(async (track) => await track.mute())).then(
              () => undefined,
            )
          : source === Track.Source.Microphone
            ? localParticipant.setMicrophoneEnabled(false)
            : localParticipant.setCameraEnabled(false);
      await this.ownMediaOperation(operation);
      this.publicationChanged$.next();
    }
  }

  private async enableParticipantSource(
    source: Track.Source,
    room: LivekitRoom,
  ): Promise<void> {
    if (!this.shouldEnableSource(source)) return;
    await this.removeUnusablePublication(source, room);
    await this.quarantineOwnedUnpublishedSourceTracks(source);
    if (!this.shouldEnableSource(source)) return;

    const existingPublication = this.getUsablePublication(source);
    const existingTrack = existingPublication?.track;
    if (existingTrack) {
      this.claimPublication(existingPublication, true);
      try {
        await existingTrack.unmute();
      } catch {
        this.logSourceUpdateFailure(source);
      }
      if (!this.shouldEnableSource(source)) {
        if (this.destroyed || this.terminallyDisconnected) {
          this.stopOwnedTrackGeneration(existingTrack);
        } else if (!existingTrack.isMuted) {
          await existingTrack.mute();
        }
        this.publicationChanged$.next();
        return;
      }
      this.publicationChanged$.next();
      if (this.isTrackResumable(existingTrack)) return;
      this.queueTrackReaper(existingTrack);
    }

    const tracks = await room.localParticipant.createTracks(
      source === Track.Source.Microphone ? { audio: true } : { video: true },
    );
    tracks.forEach((track) => this.claimTrack(track));
    const track = tracks.find((candidate) => candidate.source === source);
    tracks
      .filter((candidate) => candidate !== track)
      .forEach((candidate) =>
        this.stopAndReleaseOwnedUnpublishedTrack(candidate),
      );
    if (!track) throw new Error("LiveKit did not create the requested track");

    if (!this.shouldEnableSource(source)) {
      this.stopAndReleaseOwnedUnpublishedTrack(track);
      return;
    }

    const publicationAfterCapture = this.getResumablePublication(source);
    if (publicationAfterCapture) {
      this.claimPublication(publicationAfterCapture, true);
      this.stopAndReleaseOwnedUnpublishedTrack(track);
      return;
    }

    try {
      const publication = await room.localParticipant.publishTrack(track);
      this.forgetPendingLocalTrack(track);
      if (this.isTrackUsable(track)) this.claimPublication(publication);
      if (!this.shouldEnableSource(source) && this.isTrackUsable(track)) {
        if (this.destroyed || this.terminallyDisconnected) {
          this.stopOwnedTrackGeneration(track);
          this.queueTrackReaper(track);
        } else {
          await track.mute();
        }
      }
    } catch (error) {
      let senderFenceFailure: unknown;
      try {
        await this.fencePendingLocalSenders(track);
      } catch (fenceError) {
        senderFenceFailure = fenceError;
      }
      this.stopAndReleaseOwnedUnpublishedTrack(track);
      throw senderFenceFailure ?? error;
    }
  }

  private shouldEnableSource(source: Track.Source): boolean {
    return (
      !this.destroyed &&
      !this.terminallyDisconnected &&
      this.getDesiredSourceEnabled(source)
    );
  }

  private async quarantineOwnedUnpublishedSourceTracks(
    source: Track.Source,
  ): Promise<void> {
    const publishedTracks = this.getPublishedTracks();
    const tracks = [...this.ownedTracks].filter(
      (track) =>
        this.ownsTrack(track) &&
        track.source === source &&
        !publishedTracks.has(track) &&
        !this.isTrackPhysicallyNotSending(track),
    );
    await Promise.all(
      tracks.map(
        async (track) =>
          await this.quarantineTrackGeneration(
            this.snapshotTrackGeneration(track),
          ),
      ),
    );
  }

  private async removeUnusablePublication(
    source: Track.Source,
    room: LivekitRoom,
  ): Promise<void> {
    for (const track of this.getSourceTracks(source)) {
      if (this.isTrackUsable(track)) continue;
      this.claimTrack(track, true);
      const generation = track.mediaStreamTrack;
      const pendingCleanups = getPublicationTrackCleanups(track);
      if (pendingCleanups.length > 0) {
        await Promise.all(
          pendingCleanups.map(async ({ safePoint }) => await safePoint),
        );
        this.stopOwnedTrackGeneration(track, generation);
        continue;
      }
      await this.reapTrack(track, generation, room, source);
    }
    this.publicationChanged$.next();
  }

  private async unpublishTrack(
    track: PublicationTrack,
    room: LivekitRoom,
  ): Promise<LocalTrackPublication | undefined> {
    const generation = track.mediaStreamTrack;
    const result = await registerPublicationTrackCleanup(
      track,
      generation,
      room.localParticipant,
      async () => {
        return await room.localParticipant.unpublishTrack(track, false);
      },
      this.createCleanupSafePointDeadline(),
    );
    if (result.boundary === "deadline") {
      this.stopOwnedTrackGeneration(track, generation);
    }
    return result.publication;
  }

  private isSourceEnabled(source: Track.Source): boolean {
    const localParticipant = this.connection.livekitRoom.localParticipant;
    const publishedTrack = this.getUsablePublication(source)?.track;
    if (publishedTrack) {
      return !publishedTrack.isMuted;
    }
    return source === Track.Source.Microphone
      ? localParticipant.isMicrophoneEnabled
      : localParticipant.isCameraEnabled;
  }

  private logSourceUpdateFailure(source: Track.Source): void {
    if (source === Track.Source.Microphone) {
      this.logger.error("Failed to update LiveKit audio input mute state");
    } else {
      this.logger.error("Failed to update LiveKit video input mute state");
    }
  }

  private async waitForOperationsOrDeadline(
    operations: Set<Promise<void>>,
    deadlineReached: Promise<void>,
    hasReachedDeadline: () => boolean,
  ): Promise<void> {
    while (operations.size > 0 && !hasReachedDeadline()) {
      await Promise.race([
        Promise.all([...operations]).then(() => undefined),
        deadlineReached,
      ]);
    }
  }

  private trackCleanupOperation(operation: Promise<void>): void {
    const settled = operation.then(
      () => undefined,
      () => undefined,
    );
    this.cleanupOperations.add(settled);
    void settled.then(() => this.cleanupOperations.delete(settled));
  }

  private startCleanupAttempt(): void {
    const cleanup = this.stopTracks().catch(() => {
      this.logger.error("Failed to stop tracks");
      this.forceStopKnownTracks();
      let shouldRetry = false;
      for (const track of this.ownedTracks) {
        const generation = track.mediaStreamTrack;
        if (
          this.cleanupRetryGenerations.get(track) !== generation &&
          this.getPublishedTracks().has(track)
        ) {
          this.cleanupRetryGenerations.set(track, generation);
          shouldRetry = true;
        }
      }
      if (shouldRetry) {
        this.startCleanupAttempt();
      }
    });
    this.trackCleanupOperation(cleanup);
  }

  private queueLateCleanup(): void {
    if (!this.destroyed || this.lateCleanupQueued) return;
    this.lateCleanupQueued = true;
    queueMicrotask(() => {
      this.lateCleanupQueued = false;
      this.claimPublishedTracksForDestruction();
      this.forceStopKnownTracks();
      this.startCleanupAttempt();
    });
  }

  private claimPublishedTracksForDestruction(): void {
    if (!this.destroyed) return;
    const participant = this.connection.livekitRoom.localParticipant;
    if (
      participantPublicationGenerations.get(participant) !==
      this.publicationGeneration
    ) {
      return;
    }
    for (const track of this.getPublishedTracks()) this.claimTrack(track);
  }

  private observeLatePublicationsAfterDestruction(room: LivekitRoom): void {
    const participant = room.localParticipant;
    if (
      this.terminallyDisconnected ||
      participantPublicationGenerations.get(participant) !==
        this.publicationGeneration
    ) {
      return;
    }

    let retired = false;
    const handler = (publication: LocalTrackPublication): void => {
      if (publication.track) this.claimTrack(publication.track);
      this.queueLateCleanup();
    };
    const senderHandler = (sender: RTCRtpSender, track: Track): void => {
      const localTrack = track as PublicationTrack;
      this.claimTrack(localTrack);
      this.onLocalSenderCreated(sender, localTrack);
      this.queueLateCleanup();
    };
    const terminalHandler = (): void => {
      this.handleTerminalDisconnect();
      observer.retire();
    };
    const observer: LatePublicationObserver = {
      retire: (successor): void => {
        if (retired) return;
        retired = true;
        if (successor) {
          for (const track of [...this.ownedTracks]) {
            if (
              this.ownsTrack(track) &&
              !getParticipantScreenShareOperation(participant, track)
            ) {
              void transferPublicationTrackOwnership(track, successor);
            }
          }
        }
        participant.off(ParticipantEvent.LocalTrackPublished, handler);
        participant.off(ParticipantEvent.LocalSenderCreated, senderHandler);
        room.off(LivekitRoomEvent.Disconnected, terminalHandler);
        if (latePublicationObservers.get(participant) === observer) {
          latePublicationObservers.delete(participant);
        }
      },
    };
    latePublicationObservers.set(participant, observer);
    participant.on(ParticipantEvent.LocalTrackPublished, handler);
    participant.on(ParticipantEvent.LocalSenderCreated, senderHandler);
    room.on(LivekitRoomEvent.Disconnected, terminalHandler);
  }

  private handleTerminalDisconnect(): void {
    if (this.terminallyDisconnected) return;
    this.terminallyDisconnected = true;
    this.pendingTrackSenderObservations.clear();
    this.cancelSourceRecoveryTimers();
    this.retireScreenShareOperations();
    this.cancelPublishingIntent();
    const pendingSenderFence = this.fencePendingLocalSenders();
    void pendingSenderFence.catch(() => {
      this.logger.error(
        "Failed to fence pending local media after terminal disconnect",
      );
    });
    const room = this.connection.livekitRoom;
    room.off(LivekitRoomEvent.Connected, this.roomConnectedHandler);
    room.off(LivekitRoomEvent.Reconnected, this.roomConnectedHandler);
    for (const track of this.getPublishedTracks()) {
      this.claimTrack(track, true);
    }
    this.forceStopKnownTracks();
    this.setPublishingActive(false);
    for (const track of this.getPublishedTracks()) {
      if (this.ownsTrack(track)) {
        this.queueTrackReaper(track, track.mediaStreamTrack);
      }
    }
    this.preferredSourceTracks.clear();
    this.publicationChanged$.next();
  }

  private getSourcePublications(
    source: Track.Source,
    participant = this.connection.livekitRoom.localParticipant,
  ): LocalTrackPublication[] {
    const publications = [...participant.trackPublications.values()].filter(
      (publication) =>
        publication.source === source || publication.track?.source === source,
    );
    const directPublication = participant.getTrackPublication(source);
    if (directPublication && !publications.includes(directPublication)) {
      publications.push(directPublication);
    }
    return publications;
  }

  private getSourceTracks(
    source: Track.Source,
    participant = this.connection.livekitRoom.localParticipant,
  ): PublicationTrack[] {
    return [
      ...new Set(
        this.getSourcePublications(source, participant).flatMap(
          (publication) => (publication.track ? [publication.track] : []),
        ),
      ),
    ];
  }

  private getSafetySourceTracks(source: Track.Source): PublicationTrack[] {
    const tracks = new Set(this.getSourceTracks(source));
    for (const track of this.ownedTracks) {
      if (
        this.ownsTrack(track) &&
        track.source === source &&
        !this.isTrackPhysicallyNotSending(track)
      ) {
        tracks.add(track);
      }
    }
    return [...tracks];
  }

  private getPublishedTracks(): Set<PublicationTrack> {
    const localParticipant = this.connection.livekitRoom.localParticipant;
    const tracks = new Set<PublicationTrack>();
    for (const publication of localParticipant.trackPublications.values()) {
      if (publication.track) tracks.add(publication.track);
    }
    for (const source of [
      Track.Source.Microphone,
      Track.Source.Camera,
      Track.Source.ScreenShare,
      Track.Source.ScreenShareAudio,
    ]) {
      const publication = localParticipant.getTrackPublication(source);
      if (publication?.track) tracks.add(publication.track);
    }
    return tracks;
  }

  private getExactPublication(
    track: PublicationTrack,
    participant = this.connection.livekitRoom.localParticipant,
  ): LocalTrackPublication | undefined {
    const publication = [...participant.trackPublications.values()].find(
      (candidate) => candidate.track === track,
    );
    if (publication) return publication;
    for (const source of [
      Track.Source.Microphone,
      Track.Source.Camera,
      Track.Source.ScreenShare,
      Track.Source.ScreenShareAudio,
    ]) {
      const directPublication = participant.getTrackPublication(source);
      if (directPublication?.track === track) return directPublication;
    }
    return undefined;
  }

  private claimPublication(
    publication: LocalTrackPublication | undefined,
    transfer = false,
  ): void {
    if (publication?.track) this.claimTrack(publication.track, transfer);
  }

  private claimTrack(track: PublicationTrack, transfer = false): void {
    const currentOwner = publicationTrackOwners.get(track);
    if (
      !transfer &&
      currentOwner !== undefined &&
      currentOwner !== this.trackOwner
    ) {
      return;
    }
    const transferOperation = transferPublicationTrackOwnership(
      track,
      this.trackOwner,
    );
    if (this.ownsTrack(track)) {
      this.observeTrackState(track);
      this.consumePendingTrackSenderObservations(track);
      return;
    }
    const ownershipOperation = transferOperation
      .then((acquired): void => {
        if (!acquired || !this.ownsTrack(track)) {
          this.forgetPendingTrackSenderObservations(track);
          return;
        }
        this.observeTrackState(track);
        this.consumePendingTrackSenderObservations(track);
        this.publicationChanged$.next();
        if (this.destroyed || this.terminallyDisconnected) {
          this.stopOwnedTrackGeneration(track, track.mediaStreamTrack);
        } else if (this.isPublishingIntentCurrent()) {
          this.requestPublishingReconciliation();
        } else if (this.getExactPublication(track)) {
          this.ensureTrackPaused(track);
        }
      })
      .catch((): void => this.forgetPendingTrackSenderObservations(track));
    this.trackOwnershipOperations.add(ownershipOperation);
    void ownershipOperation.then(() => {
      this.trackOwnershipOperations.delete(ownershipOperation);
    });
  }

  private markPublicationCommitted(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    let generations = this.committedPublicationGenerations.get(track);
    if (!generations) {
      generations = new WeakSet();
      this.committedPublicationGenerations.set(track, generations);
    }
    generations.add(generation);
  }

  private clearPublicationCommitted(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    this.committedPublicationGenerations.get(track)?.delete(generation);
  }

  private isPublicationCommitted(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): boolean {
    return (
      this.committedPublicationGenerations.get(track)?.has(generation) === true
    );
  }

  private ownsTrack(track: PublicationTrack): boolean {
    return publicationTrackOwners.get(track) === this.trackOwner;
  }

  private ownsTrackGeneration(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): boolean {
    return this.ownsTrack(track) && track.mediaStreamTrack === generation;
  }

  private releaseTrack(track: PublicationTrack): void {
    this.forgetPendingLocalTrack(track);
    this.ownedTracks.delete(track);
    if (this.ownsTrack(track)) {
      publicationTrackOwners.delete(track);
      this.trackOwner.releasedTrack(track);
    }
    this.stopObservingTrackState(track);
  }

  private getRawCaptureTrack(track: PublicationTrack): MediaStreamTrack {
    const publishedTrack = track.mediaStreamTrack;
    return (
      track.mediaStream
        ?.getTracks()
        .find((candidate) => candidate.kind === publishedTrack.kind) ??
      publishedTrack
    );
  }

  private getTrackMediaGenerations(
    track: PublicationTrack,
  ): Set<MediaStreamTrack> {
    return new Set([this.getRawCaptureTrack(track), track.mediaStreamTrack]);
  }

  private observeSenderAssignments(
    track: PublicationTrack,
  ): SenderAssignmentObservation | undefined {
    const senderTrack = track as PublicationTrack & SenderAssignmentTrack;
    const original = senderTrack.setSimulcastTrackSender;
    if (!original) return undefined;
    const hadOwnMethod = Object.prototype.hasOwnProperty.call(
      senderTrack,
      "setSimulcastTrackSender",
    );
    const wrapper = (codec: unknown, sender: RTCRtpSender): void => {
      original.call(senderTrack, codec, sender);
      this.onTrackSenderDiscovered(track, sender);
    };
    senderTrack.setSimulcastTrackSender = wrapper;
    return { senderTrack, original, wrapper, hadOwnMethod };
  }

  private observeTrackState(track: PublicationTrack): void {
    const currentGenerations = this.getTrackMediaGenerations(track);
    const existing = this.trackObservations.get(track);
    if (
      existing &&
      existing.mediaGenerations.size === currentGenerations.size &&
      [...currentGenerations].every((generation) =>
        existing.mediaGenerations.has(generation),
      )
    ) {
      return;
    }

    if (existing) {
      for (const generation of existing.mediaGenerations) {
        generation.removeEventListener("mute", existing.mediaStateHandler);
        generation.removeEventListener("unmute", existing.mediaStateHandler);
        generation.removeEventListener("ended", existing.mediaStateHandler);
      }
      existing.mediaGenerations.clear();
      for (const generation of currentGenerations) {
        existing.mediaGenerations.add(generation);
        generation.addEventListener("mute", existing.mediaStateHandler);
        generation.addEventListener("unmute", existing.mediaStateHandler);
        generation.addEventListener("ended", existing.mediaStateHandler);
      }
      return;
    }

    const trackHandlers = new Map<TrackEvent, () => void>();
    const observableTrack = track as unknown as {
      on(event: TrackEvent, handler: () => void): void;
    };
    for (const event of [
      TrackEvent.Muted,
      TrackEvent.Unmuted,
      TrackEvent.Ended,
      TrackEvent.Restarted,
      TrackEvent.TrackProcessorUpdate,
      TrackEvent.UpstreamPaused,
      TrackEvent.UpstreamResumed,
    ]) {
      const handler = (): void =>
        this.onObservedTrackStateChanged(track, event);
      trackHandlers.set(event, handler);
      observableTrack.on(event, handler);
    }
    const mediaStateHandler = (): void =>
      this.onObservedTrackStateChanged(track, "media");
    for (const generation of currentGenerations) {
      generation.addEventListener("mute", mediaStateHandler);
      generation.addEventListener("unmute", mediaStateHandler);
      generation.addEventListener("ended", mediaStateHandler);
    }
    const senderAssignment = this.observeSenderAssignments(track);
    this.trackObservations.set(track, {
      mediaGenerations: currentGenerations,
      trackHandlers,
      mediaStateHandler,
      senderAssignment,
    });
  }

  private stopObservingTrackState(track: PublicationTrack): void {
    const observation = this.trackObservations.get(track);
    if (!observation) return;
    const observableTrack = track as unknown as {
      off(event: TrackEvent, handler: () => void): void;
    };
    for (const [event, handler] of observation.trackHandlers) {
      observableTrack.off(event, handler);
    }
    for (const generation of observation.mediaGenerations) {
      generation.removeEventListener("mute", observation.mediaStateHandler);
      generation.removeEventListener("unmute", observation.mediaStateHandler);
      generation.removeEventListener("ended", observation.mediaStateHandler);
    }
    const senderAssignment = observation.senderAssignment;
    if (
      senderAssignment &&
      senderAssignment.senderTrack.setSimulcastTrackSender ===
        senderAssignment.wrapper
    ) {
      if (senderAssignment.hadOwnMethod) {
        senderAssignment.senderTrack.setSimulcastTrackSender =
          senderAssignment.original;
      } else {
        delete senderAssignment.senderTrack.setSimulcastTrackSender;
      }
    }
    this.trackObservations.delete(track);
  }

  private onObservedTrackStateChanged(
    track: PublicationTrack,
    event: TrackEvent | "media",
  ): void {
    if (!this.ownsTrack(track)) return;
    this.observeTrackState(track);
    if (
      event === TrackEvent.Restarted ||
      event === TrackEvent.TrackProcessorUpdate
    ) {
      this.recordCurrentSenderAssignments(track);
    }
    if (this.destroyed || this.terminallyDisconnected) {
      const generation = track.mediaStreamTrack;
      this.stopOwnedTrackGeneration(track, generation);
      if (this.terminallyDisconnected && this.getPublishedTracks().has(track)) {
        this.queueTrackReaper(track, generation);
      }
      if (this.destroyed && this.destructionFinished) this.queueLateCleanup();
      this.publicationChanged$.next();
      return;
    }

    this.publicationChanged$.next();
    if (this.hasPendingTrackMutationOperation(track)) return;
    this.reapSourcePublications(track.source);
    if (this.isPublishingIntentCurrent()) {
      this.requestPublishingReconciliation();
    } else if (
      event === TrackEvent.UpstreamResumed ||
      event === TrackEvent.Restarted ||
      event === TrackEvent.Unmuted ||
      event === "media"
    ) {
      this.ensureTrackPaused(track);
    }
  }

  private isTrackUsable(track: PublicationTrack): boolean {
    const generation = track.mediaStreamTrack;
    return (
      this.isTrackGenerationLive(track, generation) &&
      !getPublicationTrackGenerationState(track, generation).unsafeMutation &&
      !getPublicationTrackCleanups(track).some(
        (cleanup) => cleanup.generation === generation,
      ) &&
      !hasUnsafePendingTrackMutation(track)
    );
  }

  private getSenderTargets(
    track: PublicationTrack,
  ): Map<RTCRtpSender, MediaStreamTrack> {
    let targets = publicationTrackSenderTargets.get(track);
    if (!targets) {
      targets = new Map();
      publicationTrackSenderTargets.set(track, targets);
    }
    return targets;
  }

  private recordSenderAssignment(
    track: PublicationTrack,
    generation: MediaStreamTrack,
    sender: RTCRtpSender,
  ): void {
    this.getSenderTargets(track).set(
      sender,
      this.getSenderAssignmentTarget(track, generation, sender),
    );
  }

  private getSenderAssignmentTarget(
    track: PublicationTrack,
    generation: MediaStreamTrack,
    sender: RTCRtpSender,
  ): MediaStreamTrack {
    const senderTrack = track as PublicationTrack & {
      readonly simulcastCodecs?: ReadonlyMap<
        unknown,
        {
          readonly sender?: RTCRtpSender;
          readonly mediaStreamTrack: MediaStreamTrack;
        }
      >;
    };
    const simulcast = [...(senderTrack.simulcastCodecs?.values() ?? [])].find(
      (candidate) => candidate.sender === sender,
    );
    return sender.track ?? simulcast?.mediaStreamTrack ?? generation;
  }

  private recordCurrentSenderAssignments(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
  ): void {
    this.getTrackSenderBindings(track, generation, true);
  }

  private getTrackSenderBindings(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
    recordCurrentAssignments = false,
  ): PublicationSenderBinding[] {
    const senderTrack = track as PublicationTrack & {
      readonly sender?: RTCRtpSender;
      readonly simulcastCodecs?: ReadonlyMap<
        unknown,
        {
          readonly sender?: RTCRtpSender;
          readonly mediaStreamTrack: MediaStreamTrack;
        }
      >;
    };
    const targets = this.getSenderTargets(track);
    const currentSenders = new Set<RTCRtpSender>();
    const bindings: PublicationSenderBinding[] = [];
    const addCurrent = (
      sender: RTCRtpSender,
      fallback: MediaStreamTrack,
      primary = false,
    ): void => {
      currentSenders.add(sender);
      let expectedTrack = targets.get(sender);
      if (
        !expectedTrack ||
        (primary && expectedTrack !== generation) ||
        (recordCurrentAssignments && sender.track)
      ) {
        expectedTrack = sender.track ?? fallback;
        targets.set(sender, expectedTrack);
      }
      bindings.push({
        sender,
        expectedTrack,
        current: true,
      });
    };
    if (senderTrack.sender) addCurrent(senderTrack.sender, generation, true);
    if (track.mediaStreamTrack === generation) {
      for (const simulcast of senderTrack.simulcastCodecs?.values() ?? []) {
        if (simulcast.sender) {
          addCurrent(simulcast.sender, simulcast.mediaStreamTrack);
        }
      }
    }
    for (const [sender, expectedTrack] of targets) {
      if (!currentSenders.has(sender)) {
        bindings.push({
          sender,
          expectedTrack,
          current: false,
        });
      }
    }
    return bindings;
  }

  private snapshotTrackGeneration(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
  ): PublicationTrackGeneration {
    return {
      track,
      generation,
      senderBindings: this.getTrackSenderBindings(track, generation),
    };
  }

  private isSenderTransportHealthy(sender: RTCRtpSender): boolean {
    const state = sender.transport?.state;
    return state !== "closed" && state !== "failed";
  }

  private isSenderBindingActive(binding: PublicationSenderBinding): boolean {
    const senderTrack = binding.sender.track;
    return (
      this.isSenderTransportHealthy(binding.sender) &&
      senderTrack !== null &&
      senderTrack === binding.expectedTrack &&
      senderTrack.readyState !== "ended" &&
      senderTrack.muted !== true &&
      senderTrack.enabled !== false
    );
  }

  private isSenderBindingNotSending(
    binding: PublicationSenderBinding,
  ): boolean {
    return binding.sender.track === null;
  }

  private isTrackCaptureHealthy(track: PublicationTrack): boolean {
    return (
      this.isTrackUsable(track) &&
      !track.isMuted &&
      [...this.getTrackMediaGenerations(track)].every(
        (mediaStreamTrack) =>
          mediaStreamTrack.readyState !== "ended" &&
          mediaStreamTrack.muted !== true &&
          mediaStreamTrack.enabled !== false,
      )
    );
  }

  private isTrackResumable(track: PublicationTrack): boolean {
    const bindings = this.getTrackSenderBindings(track);
    const currentBindings = bindings.filter(({ current }) => current);
    return (
      this.isTrackCaptureHealthy(track) &&
      currentBindings.length > 0 &&
      bindings
        .filter(({ current }) => !current)
        .every((binding) => this.isSenderBindingNotSending(binding)) &&
      (track.isUpstreamPaused === true ||
        currentBindings.some((binding) => this.isSenderBindingActive(binding)))
    );
  }

  private isTrackHealthy(track: PublicationTrack): boolean {
    const bindings = this.getTrackSenderBindings(track);
    const currentBindings = bindings.filter(({ current }) => current);
    return (
      this.isTrackCaptureHealthy(track) &&
      track.isUpstreamPaused === false &&
      currentBindings.length > 0 &&
      currentBindings.every((binding) => this.isSenderBindingActive(binding)) &&
      bindings
        .filter(({ current }) => !current)
        .every((binding) => this.isSenderBindingNotSending(binding))
    );
  }

  private markControlledPausedGeneration(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    let generations = this.controlledPausedGenerations.get(track);
    if (!generations) {
      generations = new WeakSet();
      this.controlledPausedGenerations.set(track, generations);
    }
    generations.add(generation);
  }

  private isControlledPausedGeneration(
    track: PublicationTrack | undefined,
    generation: MediaStreamTrack,
  ): boolean {
    return (
      track !== undefined &&
      this.controlledPausedGenerations.get(track)?.has(generation) === true
    );
  }

  private clearControlledPausedGeneration(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    this.controlledPausedGenerations.get(track)?.delete(generation);
  }

  private markAuthoritativeResumeGeneration(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    let generations = this.authoritativeResumeGenerations.get(track);
    if (!generations) {
      generations = new WeakSet();
      this.authoritativeResumeGenerations.set(track, generations);
    }
    generations.add(generation);
  }

  private isAuthoritativeResumeGeneration(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): boolean {
    return (
      this.authoritativeResumeGenerations.get(track)?.has(generation) === true
    );
  }

  private clearAuthoritativeResumeGeneration(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    this.authoritativeResumeGenerations.get(track)?.delete(generation);
  }

  private isTrackNotSending(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
    senderBindings?: readonly PublicationSenderBinding[],
  ): boolean {
    const bindingsBySender = new Map<RTCRtpSender, PublicationSenderBinding>();
    for (const binding of [
      ...(senderBindings ?? []),
      ...this.getTrackSenderBindings(track, generation),
      ...(track.mediaStreamTrack === generation
        ? []
        : this.getTrackSenderBindings(track, track.mediaStreamTrack)),
    ]) {
      bindingsBySender.set(binding.sender, binding);
    }
    const bindings = [...bindingsBySender.values()];
    return bindings.every((binding) => this.isSenderBindingNotSending(binding));
  }

  private isTrackPhysicallyNotSending(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
  ): boolean {
    return this.getTrackSenderBindings(track, generation).every(
      ({ sender, current }) =>
        sender.track === null ||
        (current && sender.track.readyState === "ended"),
    );
  }

  private isTrackGenerationLive(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
  ): boolean {
    return (
      !isPublicationTrackGenerationStopped(track, generation) &&
      generation.readyState !== "ended"
    );
  }

  private stopOwnedTrackGeneration(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
  ): boolean {
    if (!this.ownsTrack(track)) return false;
    const state = getPublicationTrackGenerationState(track, generation);
    if (state.stopped) {
      this.stopObservedSenderTracks(track);
      return true;
    }
    this.clearControlledPausedGeneration(track, generation);
    state.stopped = true;
    try {
      if (track.mediaStreamTrack === generation) track.stop();
      else if (generation.readyState !== "ended") generation.stop();
      this.stopObservedSenderTracks(track);
      return true;
    } catch {
      state.stopped = false;
      this.stopObservedSenderTracks(track);
      this.logger.error("Failed to stop local media track");
      return false;
    }
  }

  private stopObservedSenderTracks(track: PublicationTrack): void {
    const targets = publicationTrackSenderTargets.get(track);
    if (!targets) return;
    for (const [sender, expectedTrack] of targets) {
      for (const mediaStreamTrack of new Set([
        expectedTrack,
        ...(sender.track ? [sender.track] : []),
      ])) {
        if (mediaStreamTrack.readyState === "ended") continue;
        try {
          mediaStreamTrack.stop();
        } catch {
          this.logger.error("Failed to stop an observed local sender track");
        }
      }
    }
  }

  private stopAndReleaseOwnedUnpublishedTrack(track: PublicationTrack): void {
    this.stopOwnedTrackGeneration(track);
    this.forgetPendingLocalTrack(track);
    this.releaseStoppedUnpublishedTrack(track);
  }

  private releaseStoppedUnpublishedTrack(track: PublicationTrack): void {
    if (
      this.ownsTrack(track) &&
      this.mediaOperations.size === 0 &&
      !this.getPublishedTracks().has(track) &&
      this.isTrackPhysicallyNotSending(track) &&
      (publicationTrackDetachOperations.get(track)?.size ?? 0) === 0 &&
      getPublicationTrackGenerationState(track).stopped
    ) {
      this.releaseTrack(track);
    }
  }

  private releaseStoppedUnpublishedTracks(): void {
    for (const track of [...this.ownedTracks]) {
      this.releaseStoppedUnpublishedTrack(track);
    }
  }

  private stopOwnedUnpublishedTracks(
    source?: Track.Source,
    release = false,
  ): void {
    const publishedTracks = this.getPublishedTracks();
    for (const track of this.ownedTracks) {
      if (
        !publishedTracks.has(track) &&
        (source === undefined || track.source === source)
      ) {
        const senderFence = this.fencePendingLocalSenders(track);
        void senderFence.catch(() => {
          this.logger.error(
            "Failed to fence an unpublished local media sender",
          );
        });
        if (release) this.stopAndReleaseOwnedUnpublishedTrack(track);
        else this.stopOwnedTrackGeneration(track);
      }
    }
  }

  private forceStopKnownTracks(): void {
    for (const track of this.ownedTracks) {
      this.stopOwnedTrackGeneration(track);
    }
  }

  private onTimedOutTrackCleanupSettled(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    if (!this.ownsTrack(track)) return;
    if (!this.getPublishedTracks().has(track)) {
      this.releaseStoppedUnpublishedTrack(track);
      return;
    }
    if (track.mediaStreamTrack === generation) {
      this.queueTrackReaper(track, generation);
    } else if (this.shouldReapCurrentTrack(track)) {
      this.queueTrackReaper(track, track.mediaStreamTrack);
    }
    this.publicationChanged$.next();
  }

  private onLateTrackMutationSettled(
    track: PublicationTrack,
    generation: MediaStreamTrack,
  ): void {
    if (!this.ownsTrack(track)) return;
    const currentGeneration = track.mediaStreamTrack;
    getPublicationTrackGenerationState(track, generation).unsafeMutation = true;
    getPublicationTrackGenerationState(
      track,
      currentGeneration,
    ).unsafeMutation = true;
    this.stopOwnedTrackGeneration(track, generation);
    this.stopOwnedTrackGeneration(track, currentGeneration);
    if (this.getPublishedTracks().has(track)) {
      this.queueTrackReaper(track, currentGeneration);
    } else {
      this.releaseStoppedUnpublishedTrack(track);
    }
    this.publicationChanged$.next();
  }

  private queueTrackReaper(
    track: PublicationTrack,
    generation = track.mediaStreamTrack,
    source = track.source,
  ): void {
    let queuedGenerations = this.queuedTrackReaperGenerations.get(track);
    if (!queuedGenerations) {
      queuedGenerations = new Set();
      this.queuedTrackReaperGenerations.set(track, queuedGenerations);
    }
    if (queuedGenerations.has(generation)) return;
    queuedGenerations.add(generation);
    queueMicrotask(() => {
      queuedGenerations.delete(generation);
      if (queuedGenerations.size === 0) {
        this.queuedTrackReaperGenerations.delete(track);
      }
      const cleanup = this.reapTrack(
        track,
        generation,
        this.connection.livekitRoom,
        source,
      ).catch(() => {
        this.logger.error("Failed to reap stale local media");
      });
      this.trackCleanupOperation(cleanup);
    });
  }

  private async reapTrack(
    track: PublicationTrack,
    generation: MediaStreamTrack,
    room: LivekitRoom,
    source: Track.Source,
  ): Promise<void> {
    if (!this.ownsTrack(track)) return;
    if (
      !this.destroyed &&
      !this.terminallyDisconnected &&
      this.hasPendingTrackMutationOperation(track)
    ) {
      return;
    }
    const publication = this.getExactPublication(track, room.localParticipant);
    if (!publication) {
      this.stopOwnedTrackGeneration(track, generation);
      this.releaseStoppedUnpublishedTrack(track);
      return;
    }
    if (
      track.source !== source ||
      (publication.source !== source && publication.track?.source !== source)
    ) {
      const currentSource = track.source;
      if (this.shouldReapCurrentTrack(track, currentSource)) {
        this.queueTrackReaper(track, track.mediaStreamTrack, currentSource);
      }
      this.publicationChanged$.next();
      return;
    }
    if (track.mediaStreamTrack !== generation) {
      this.stopOwnedTrackGeneration(track, generation);
      const currentGeneration = track.mediaStreamTrack;
      if (this.shouldReapCurrentTrack(track, source)) {
        this.queueTrackReaper(track, currentGeneration, source);
      }
      this.publicationChanged$.next();
      return;
    }
    if (hasUnsafePendingTrackMutation(track)) return;
    if (!this.shouldReapCurrentTrack(track, source)) return;

    this.stopOwnedTrackGeneration(track, generation);

    await this.unpublishTrack(track, room);
    if (this.getPublishedTracks().has(track)) {
      throw new Error("LiveKit retained a stopped local track publication");
    }
    this.releaseStoppedUnpublishedTrack(track);
    this.publicationChanged$.next();
  }

  private shouldReapCurrentTrack(
    track: PublicationTrack,
    source = track.source,
  ): boolean {
    if (this.destroyed || this.terminallyDisconnected) return true;
    if (this.hasPendingTrackMutationOperation(track)) return false;
    const preferredPublication =
      this.getControlledPausedPublication(source) ??
      this.getHealthyPublication(source) ??
      this.getResumablePublication(source);
    const preferredTrack = preferredPublication?.track;
    if (
      preferredTrack === track &&
      track.mediaStreamTrack ===
        this.preferredSourceTracks.get(source)?.generation &&
      this.isTrackResumable(track)
    ) {
      return false;
    }
    if (
      preferredTrack === undefined &&
      track.isMuted &&
      this.isTrackUsable(track)
    ) {
      return false;
    }
    return true;
  }

  private reapSourcePublications(source: Track.Source): void {
    for (const track of this.getSourceTracks(source)) {
      if (!this.shouldReapCurrentTrack(track, source)) continue;
      this.claimTrack(track, true);
      if (!this.ownsTrack(track)) continue;
      this.queueTrackReaper(track, track.mediaStreamTrack, source);
    }
  }

  private reapUnusablePublications(): void {
    for (const source of [
      Track.Source.Microphone,
      Track.Source.Camera,
      Track.Source.ScreenShare,
      Track.Source.ScreenShareAudio,
    ]) {
      this.reapSourcePublications(source);
    }
  }

  private areSourcesNotSending(sources: Track.Source[]): boolean {
    const sourceSet = new Set(sources);
    return (
      [...sourceSet].every((source) =>
        this.getSafetySourceTracks(source).every((track) =>
          this.isTrackNotSending(track),
        ),
      ) &&
      [...this.pendingLocalSenders].every(
        ([sender, pending]) =>
          !sourceSet.has(pending.track.source) || sender.track === null,
      ) &&
      [...this.pendingTrackSenderObservations].every(
        ([sender, pending]) =>
          !sourceSet.has(pending.track.source) || sender.track === null,
      )
    );
  }

  private getFreshSenderBindings(
    snapshot: PublicationTrackGeneration,
  ): PublicationSenderBinding[] {
    const bindings = new Map<RTCRtpSender, PublicationSenderBinding>();
    for (const binding of [
      ...(snapshot.senderBindings ?? []),
      ...this.getTrackSenderBindings(snapshot.track, snapshot.generation),
      ...(snapshot.track.mediaStreamTrack === snapshot.generation
        ? []
        : this.getTrackSenderBindings(
            snapshot.track,
            snapshot.track.mediaStreamTrack,
          )),
    ]) {
      bindings.set(binding.sender, binding);
    }
    return [...bindings.values()];
  }

  private async runUpstreamControlOperation(
    operation: Promise<void>,
  ): Promise<
    | { readonly kind: "fulfilled" }
    | { readonly kind: "rejected"; readonly reason: unknown }
    | { readonly kind: "deadline" }
  > {
    const deadline = this.createUpstreamControlDeadline();
    const outcome = await Promise.race([
      operation.then(
        () => ({ kind: "fulfilled" as const }),
        (reason: unknown) => ({ kind: "rejected" as const, reason }),
      ),
      deadline.reached.then(() => ({ kind: "deadline" as const })),
    ]);
    deadline.cancel();
    return outcome;
  }

  private async replaceSenderTrackWithDeadline(
    sender: RTCRtpSender,
    replacement: MediaStreamTrack | null,
    onLateFulfilled?: () => Promise<void>,
    mutationSnapshot?: Pick<PublicationTrackGeneration, "track" | "generation">,
  ): Promise<void> {
    if (sender.track === replacement) return;
    if (
      mutationSnapshot &&
      !this.ownsTrackGeneration(
        mutationSnapshot.track,
        mutationSnapshot.generation,
      )
    ) {
      throw new Error("Local media sender mutation ownership changed");
    }
    let rawOperation: Promise<void>;
    try {
      rawOperation = Promise.resolve(sender.replaceTrack(replacement));
    } catch (error) {
      rawOperation = Promise.reject(error);
    }
    let operation = rawOperation.then(() => {
      if (
        mutationSnapshot &&
        !this.ownsTrackGeneration(
          mutationSnapshot.track,
          mutationSnapshot.generation,
        )
      ) {
        throw new Error("Local media sender mutation generation changed");
      }
    });
    if (mutationSnapshot) {
      operation = registerPublicationTrackDetachOperation(
        mutationSnapshot.track,
        operation,
      );
    }
    const outcome = await this.runUpstreamControlOperation(operation);
    if (outcome.kind === "deadline") {
      if (onLateFulfilled) {
        let compensation = operation.then(
          async () => {
            try {
              await onLateFulfilled();
            } catch {
              this.logger.error(
                "Failed to quarantine a late local sender replacement",
              );
            }
          },
          () => undefined,
        );
        if (mutationSnapshot) {
          compensation = registerPublicationTrackDetachOperation(
            mutationSnapshot.track,
            compensation,
          );
        }
        void compensation;
      }
      throw new Error("Timed out while replacing an exact local media sender");
    }
    if (outcome.kind === "rejected") throw outcome.reason;
  }

  private async detachTrackSenders(
    snapshot: PublicationTrackGeneration,
  ): Promise<boolean> {
    for (let pass = 0; pass < 2; pass += 1) {
      if (!this.ownsTrackGeneration(snapshot.track, snapshot.generation)) {
        return false;
      }
      const attachedSenders = this.getFreshSenderBindings(snapshot).filter(
        ({ sender }) => sender.track !== null,
      );
      if (attachedSenders.length === 0) return true;
      await Promise.allSettled(
        attachedSenders.map(
          async ({ sender }) =>
            await this.replaceSenderTrackWithDeadline(
              sender,
              null,
              undefined,
              snapshot,
            ),
        ),
      );
    }
    return (
      this.ownsTrackGeneration(snapshot.track, snapshot.generation) &&
      this.getFreshSenderBindings(snapshot).every(
        ({ sender }) => sender.track === null,
      )
    );
  }

  private observeLateTrackControlSettlement(
    operation: Promise<void>,
    snapshot: PublicationTrackGeneration,
  ): void {
    void operation.then(
      async () => {
        const detached = await this.detachTrackSenders(snapshot);
        if (!detached && this.getPublishedTracks().has(snapshot.track)) {
          await this.quarantineTrackGeneration(snapshot);
        }
      },
      () => undefined,
    );
  }

  private async quarantineTrackGeneration(
    snapshot: PublicationTrackGeneration,
  ): Promise<void> {
    const { track, generation } = snapshot;
    if (!this.ownsTrack(track)) return;
    if (this.ownsTrackGeneration(track, generation)) {
      await this.detachTrackSenders(snapshot);
    }
    if (!this.ownsTrack(track)) return;
    if (this.ownsTrack(track)) {
      this.stopOwnedTrackGeneration(track, generation);
      if (track.mediaStreamTrack !== generation) {
        this.stopOwnedTrackGeneration(track, track.mediaStreamTrack);
      }
    }
    if (this.ownsTrack(track) && this.getExactPublication(track)) {
      try {
        await this.unpublishTrack(track, this.connection.livekitRoom);
      } catch {
        this.logger.error("Failed to quarantine an exact local media track");
      }
    }
    if (this.ownsTrackGeneration(track, generation)) {
      await this.detachTrackSenders(snapshot);
    }
    if (!this.ownsTrack(track)) return;
    if (this.getPublishedTracks().has(track)) {
      this.queueTrackReaper(track, track.mediaStreamTrack);
    } else {
      this.releaseStoppedUnpublishedTrack(track);
    }
    this.publicationChanged$.next();
  }

  private async pauseUpstreams(
    lkRoom: LivekitRoom,
    sources: Track.Source[],
  ): Promise<void> {
    const trackGenerations: PublicationTrackGeneration[] = [];
    for (const source of new Set(sources)) {
      const tracks = this.getSourceTracks(
        source,
        lkRoom.localParticipant,
      ).filter(
        (track) =>
          this.ownsTrack(track) &&
          (this.isTrackGenerationLive(track) || !this.isTrackNotSending(track)),
      );
      if (tracks.length > 0) {
        trackGenerations.push(
          ...tracks.map((track) => this.snapshotTrackGeneration(track)),
        );
      } else {
        this.logger.warn(
          `No track found for source ${source} to pause upstream`,
        );
      }
    }
    await this.pauseTrackGenerationsFailClosed(trackGenerations);
  }

  private async pauseTrackGenerationsFailClosed(
    trackGenerations: PublicationTrackGeneration[],
  ): Promise<void> {
    const snapshots = trackGenerations.map(
      ({ track, generation, senderBindings }) =>
        senderBindings
          ? { track, generation, senderBindings }
          : this.snapshotTrackGeneration(track, generation),
    );
    const activelySendingSnapshots = new Set(
      snapshots.filter(
        ({ track, generation, senderBindings }) =>
          !this.isTrackNotSending(track, generation, senderBindings),
      ),
    );
    const liveTrackGenerations = snapshots.filter(
      ({ track, generation, senderBindings }) =>
        this.isTrackGenerationLive(track, generation) ||
        !this.isTrackNotSending(track, generation, senderBindings),
    );
    const results = await Promise.allSettled(
      liveTrackGenerations.map(async (snapshot) => {
        const previousOperation = this.trackControlOperations.get(
          snapshot.track,
        );
        const pauseOperation = (async (): Promise<void> => {
          if (previousOperation) await previousOperation;
          const operation = registerPublicationTrackDetachOperation(
            snapshot.track,
            Promise.resolve().then(async () => {
              if (
                !this.ownsTrackGeneration(snapshot.track, snapshot.generation)
              ) {
                throw new Error("Local media pause ownership changed");
              }
              await snapshot.track.pauseUpstream();
              if (
                !this.ownsTrackGeneration(snapshot.track, snapshot.generation)
              ) {
                throw new Error("Local media pause generation changed");
              }
            }),
          );
          const outcome = await this.runUpstreamControlOperation(operation);
          if (outcome.kind === "deadline") {
            this.observeLateTrackControlSettlement(operation, snapshot);
            await this.quarantineTrackGeneration(snapshot);
            throw new Error(
              "Timed out while pausing an exact local media upstream",
            );
          }
          if (outcome.kind === "rejected") {
            await this.quarantineTrackGeneration(snapshot);
            throw outcome.reason;
          }
          if (!(await this.detachTrackSenders(snapshot))) {
            await this.quarantineTrackGeneration(snapshot);
            throw new Error("An exact local media upstream remained active");
          }
        })();
        this.trackControlOperations.set(snapshot.track, pauseOperation);
        void pauseOperation.then(
          () => {
            if (
              this.trackControlOperations.get(snapshot.track) === pauseOperation
            ) {
              this.trackControlOperations.delete(snapshot.track);
            }
          },
          () => {
            if (
              this.trackControlOperations.get(snapshot.track) === pauseOperation
            ) {
              this.trackControlOperations.delete(snapshot.track);
            }
          },
        );
        return await pauseOperation;
      }),
    );

    for (const snapshot of snapshots) {
      if (!this.isTrackNotSending(snapshot.track, snapshot.generation)) {
        if (!(await this.detachTrackSenders(snapshot))) {
          await this.quarantineTrackGeneration(snapshot);
        }
      }
    }
    for (const snapshot of snapshots) {
      if (
        activelySendingSnapshots.has(snapshot) &&
        this.isTrackGenerationLive(snapshot.track, snapshot.generation) &&
        this.isTrackNotSending(snapshot.track, snapshot.generation)
      ) {
        this.markControlledPausedGeneration(
          snapshot.track,
          snapshot.generation,
        );
      }
    }
    this.publicationChanged$.next();

    const unsafeGeneration = snapshots.find(
      ({ track, generation }) => !this.isTrackNotSending(track, generation),
    );
    if (unsafeGeneration) {
      throw new Error("Failed to stop an exact local media upstream");
    }
    const failure = results.find(
      (result): result is PromiseRejectedResult => result.status === "rejected",
    );
    if (failure) throw failure.reason;
  }

  private async resumeUpstreams(
    lkRoom: LivekitRoom,
    sources: Track.Source[],
    controlGeneration: number,
    resumedTrackGenerations: PublicationTrackGeneration[],
  ): Promise<void> {
    const operations: Promise<void>[] = [];
    for (const source of new Set(sources)) {
      const preferredTrack = (
        this.getControlledPausedPublication(source) ??
        this.getHealthyPublication(source) ??
        this.getResumablePublication(source)
      )?.track;
      if (preferredTrack) {
        const generation = preferredTrack.mediaStreamTrack;
        const pendingTrackControl =
          this.trackControlOperations.get(preferredTrack);
        if (!this.isTrackHealthy(preferredTrack) || pendingTrackControl) {
          const snapshot = this.snapshotTrackGeneration(
            preferredTrack,
            generation,
          );
          resumedTrackGenerations.push(snapshot);
          operations.push(
            Promise.resolve()
              .then(async () => {
                if (pendingTrackControl) await pendingTrackControl;
                const safeToResume = await this.waitForPausedSenderSafePoint(
                  snapshot,
                  controlGeneration,
                );
                if (
                  safeToResume &&
                  this.isPublishingControlCurrent(controlGeneration) &&
                  !this.isTrackHealthy(preferredTrack)
                ) {
                  await this.resumeTrackGenerationWithDeadline(
                    snapshot,
                    controlGeneration,
                  );
                }
              })
              .then(async () => {
                if (!this.isPublishingControlCurrent(controlGeneration)) {
                  await this.pauseTrackGenerationsFailClosed([snapshot]);
                }
              }),
          );
        }
        for (const track of this.getSourceTracks(
          source,
          lkRoom.localParticipant,
        )) {
          if (
            this.ownsTrack(track) &&
            track !== preferredTrack &&
            (this.isTrackGenerationLive(track) ||
              !this.isTrackNotSending(track))
          ) {
            const duplicateGeneration = track.mediaStreamTrack;
            operations.push(
              this.pauseTrackGenerationsFailClosed([
                this.snapshotTrackGeneration(track, duplicateGeneration),
              ]),
            );
            this.queueTrackReaper(track, duplicateGeneration, source);
          }
        }
      } else {
        this.logger.warn(
          `No track found for source ${source} to resume upstream`,
        );
      }
    }
    const results = await Promise.allSettled(operations);
    const failure = results.find(
      (result): result is PromiseRejectedResult => result.status === "rejected",
    );
    for (const { track, generation } of resumedTrackGenerations) {
      if (track.mediaStreamTrack === generation && this.isTrackHealthy(track)) {
        this.clearControlledPausedGeneration(track, generation);
      }
    }
    if (failure) throw failure.reason;
  }

  private prepareProcessorResumeTargets(track: PublicationTrack): {
    restore(): void;
    stopOriginals(): void;
  } {
    const processorTrack = track as PublicationTrack & {
      getProcessor?():
        | { readonly processedTrack?: MediaStreamTrack }
        | undefined;
      readonly simulcastCodecs?: ReadonlyMap<
        unknown,
        { mediaStreamTrack: MediaStreamTrack; sender?: RTCRtpSender }
      >;
    };
    const processedTrack = processorTrack.getProcessor?.()?.processedTrack;
    this.getTrackSenderBindings(track);
    const originals: Array<{
      simulcast: { mediaStreamTrack: MediaStreamTrack };
      mediaStreamTrack: MediaStreamTrack;
    }> = [];
    if (processedTrack) {
      for (const simulcast of processorTrack.simulcastCodecs?.values() ?? []) {
        const rememberedTarget = simulcast.sender
          ? this.getSenderTargets(track).get(simulcast.sender)
          : undefined;
        const resumeTarget =
          rememberedTarget === processedTrack ||
          rememberedTarget === simulcast.mediaStreamTrack
            ? rememberedTarget
            : processedTrack;
        if (simulcast.mediaStreamTrack !== resumeTarget) {
          originals.push({
            simulcast,
            mediaStreamTrack: simulcast.mediaStreamTrack,
          });
          simulcast.mediaStreamTrack = resumeTarget;
        }
      }
    }
    return {
      restore: (): void => {
        for (const { simulcast, mediaStreamTrack } of originals) {
          if (simulcast.mediaStreamTrack === processedTrack) {
            simulcast.mediaStreamTrack = mediaStreamTrack;
          }
        }
      },
      stopOriginals: (): void => {
        for (const { mediaStreamTrack } of originals) {
          if (mediaStreamTrack.readyState !== "ended") mediaStreamTrack.stop();
        }
      },
    };
  }

  private async alignSenderTargets(
    snapshot: PublicationTrackGeneration,
  ): Promise<void> {
    if (!this.ownsTrackGeneration(snapshot.track, snapshot.generation)) {
      throw new Error("Local media resume ownership changed");
    }
    const bindings = this.getFreshSenderBindings(snapshot);
    const results = await Promise.allSettled(
      bindings.map(async ({ sender, expectedTrack, current }) => {
        if (!current && sender.track !== null) {
          await this.replaceSenderTrackWithDeadline(
            sender,
            null,
            undefined,
            snapshot,
          );
        } else if (current && sender.track !== expectedTrack) {
          await this.replaceSenderTrackWithDeadline(
            sender,
            expectedTrack,
            async () => {
              if (
                !this.ownsTrackGeneration(snapshot.track, snapshot.generation)
              ) {
                return;
              }
              getPublicationTrackGenerationState(
                snapshot.track,
                snapshot.generation,
              ).unsafeMutation = true;
              if (sender.track !== expectedTrack) return;
              await this.quarantineTrackGeneration({
                ...snapshot,
                senderBindings: [
                  ...(snapshot.senderBindings ?? []),
                  {
                    sender,
                    expectedTrack,
                    current: true,
                  },
                ],
              });
            },
            snapshot,
          );
        }
      }),
    );
    const failure = results.find(
      (result): result is PromiseRejectedResult => result.status === "rejected",
    );
    if (failure) throw failure.reason;
    const unhealthyBindings = this.getFreshSenderBindings(snapshot).filter(
      (binding) =>
        binding.current
          ? !this.isSenderBindingActive(binding)
          : !this.isSenderBindingNotSending(binding),
    );
    if (unhealthyBindings.length > 0) {
      throw new Error(`${snapshot.track.source} upstream is unavailable`);
    }
  }

  private async rollbackResumedTrack(
    snapshot: PublicationTrackGeneration,
  ): Promise<void> {
    try {
      await this.pauseTrackGenerationsFailClosed([snapshot]);
    } catch {
      await this.quarantineTrackGeneration(snapshot);
    }
  }

  private async resumeTrackGenerationWithDeadline(
    snapshot: PublicationTrackGeneration,
    controlGeneration: number,
  ): Promise<void> {
    this.markAuthoritativeResumeGeneration(snapshot.track, snapshot.generation);
    try {
      const processorTargets = this.prepareProcessorResumeTargets(
        snapshot.track,
      );
      const operation = Promise.resolve().then(
        async () => await snapshot.track.resumeUpstream(),
      );
      const outcome = await this.runUpstreamControlOperation(operation);
      if (outcome.kind === "deadline") {
        processorTargets.stopOriginals();
        void operation.then(
          async () => {
            processorTargets.restore();
            await this.detachTrackSenders(snapshot);
          },
          () => processorTargets.restore(),
        );
        await this.quarantineTrackGeneration(snapshot);
        throw new Error(
          "Timed out while resuming an exact local media upstream",
        );
      }
      processorTargets.restore();
      if (outcome.kind === "rejected") {
        await this.rollbackResumedTrack(snapshot);
        throw outcome.reason;
      }
      try {
        await this.fencePendingLocalSenders(snapshot.track);
      } catch (error) {
        await this.rollbackResumedTrack(snapshot);
        throw error;
      }
      if (!this.isPublishingControlCurrent(controlGeneration)) {
        await this.rollbackResumedTrack(snapshot);
        return;
      }
      try {
        await this.alignSenderTargets(snapshot);
      } catch (error) {
        await this.rollbackResumedTrack(snapshot);
        throw error;
      }
    } finally {
      this.clearAuthoritativeResumeGeneration(
        snapshot.track,
        snapshot.generation,
      );
    }
  }

  private async waitForPausedSenderSafePoint(
    snapshot: PublicationTrackGeneration,
    controlGeneration: number,
  ): Promise<boolean> {
    const { track, generation } = snapshot;
    if (
      track.isUpstreamPaused !== true ||
      this.isTrackNotSending(track, generation, snapshot.senderBindings)
    ) {
      return true;
    }

    const safePoint = Promise.withResolvers<"ready" | "obsolete">();
    let pollTimer: ReturnType<typeof setTimeout> | undefined;
    const poll = (): void => {
      if (
        !this.isPublishingControlCurrent(controlGeneration) ||
        !this.ownsTrack(track)
      ) {
        safePoint.resolve("obsolete");
      } else if (
        this.isTrackNotSending(track, generation, snapshot.senderBindings)
      ) {
        safePoint.resolve("ready");
      } else {
        pollTimer = setTimeout(poll, 25);
      }
    };
    poll();

    const deadline = this.createUpstreamControlDeadline();
    const outcome = await Promise.race([
      safePoint.promise,
      deadline.reached.then(() => "deadline" as const),
    ]);
    deadline.cancel();
    if (pollTimer !== undefined) clearTimeout(pollTimer);

    if (outcome === "deadline") {
      if (this.ownsTrack(track)) {
        await this.quarantineTrackGeneration(snapshot);
      }
      throw new Error(
        "Timed out waiting for an automatic upstream pause safe point",
      );
    }
    return outcome === "ready";
  }

  private isPublishingControlCurrent(controlGeneration: number): boolean {
    return (
      !this.destroyed &&
      !this.terminallyDisconnected &&
      participantPublicationGenerations.get(
        this.connection.livekitRoom.localParticipant,
      ) === this.publicationGeneration &&
      controlGeneration === this.publishingControlGeneration &&
      this.publishingRequested &&
      this.matrixRTCConnected
    );
  }

  private isPublishingIntentCurrent(): boolean {
    return this.isPublishingControlCurrent(this.publishingControlGeneration);
  }

  private assertHealthyUpstreamsActive(sources: Track.Source[]): void {
    for (const source of this.getRequestedSources()) {
      if (!this.getHealthyPublication(source)?.track) {
        throw new Error(`The requested ${source} upstream is unavailable`);
      }
    }
    for (const source of new Set(sources)) {
      if (
        this.getResumablePublication(source)?.track &&
        !this.getHealthyPublication(source)?.track
      ) {
        throw new Error(`The ${source} upstream remained paused or unhealthy`);
      }
    }
    if (this.hasUncontrolledPublications()) {
      throw new Error("Local media still has an uncontrolled publication");
    }
  }

  private async resumePublishing(controlGeneration: number): Promise<void> {
    if (this.destroyed || this.terminallyDisconnected) {
      throw new Error("Publisher was destroyed");
    }
    if (
      controlGeneration !== this.publishingControlGeneration ||
      !this.publishingRequested ||
      !this.matrixRTCConnected
    ) {
      return;
    }

    const sources = [
      Track.Source.Microphone,
      Track.Source.Camera,
      Track.Source.ScreenShare,
      Track.Source.ScreenShareAudio,
    ];
    const resumedTrackGenerations: PublicationTrackGeneration[] = [];
    try {
      await this.waitForTrackOwnershipOperations();
      await Promise.all(
        sources.map(
          async (source) => await this.waitForSourceEnableOperations(source),
        ),
      );
      if (this.destroyed || this.terminallyDisconnected) {
        throw new Error("Publisher was destroyed");
      }
      if (
        controlGeneration !== this.publishingControlGeneration ||
        !this.publishingRequested ||
        !this.matrixRTCConnected
      ) {
        return;
      }
      await this.resumeUpstreams(
        this.connection.livekitRoom,
        sources,
        controlGeneration,
        resumedTrackGenerations,
      );
      if (this.destroyed || this.terminallyDisconnected) {
        throw new Error("Publisher was destroyed");
      }
      if (!this.isPublishingControlCurrent(controlGeneration)) {
        await this.pauseTrackGenerationsFailClosed(resumedTrackGenerations);
        return;
      }
      this.assertHealthyUpstreamsActive(sources);
      this.setPublishingActive(true);
      this.publicationChanged$.next();
    } catch (error) {
      try {
        await this.pauseTrackGenerationsFailClosed(resumedTrackGenerations);
      } catch {
        this.logger.error("Failed to roll back local media upstreams");
      }
      if (
        controlGeneration === this.publishingControlGeneration &&
        this.areSourcesNotSending(sources)
      ) {
        this.setPublishingActive(false);
        this.publicationChanged$.next();
      }
      throw error;
    }
  }

  /**
   *
   * Request to publish local tracks to the LiveKit room.
   * This will wait for the connection to be ready before publishing.
   * Livekit also have some local retry logic for publishing tracks.
   * Can be called multiple times, localparticipant manages the state of published tracks (or pending publications).
   *
   * @returns
   */
  private async runPublishingReconciliation(
    controlGeneration: number,
  ): Promise<void> {
    const previousOperation = this.startPublishingOperation;
    const reconciliation = Promise.resolve().then(async () => {
      if (previousOperation) {
        try {
          await previousOperation;
        } catch {
          // A newer request still needs to reconcile after an earlier failure.
        }
      }
      await this.resumePublishing(controlGeneration);
    });
    const operation = this.ownMediaOperation(reconciliation);
    this.startPublishingOperation = operation;
    const settled = (): void => {
      if (this.startPublishingOperation === operation) {
        this.startPublishingOperation = undefined;
      }
    };
    void operation.then(settled, settled);
    return await operation;
  }

  public async startPublishing(): Promise<void> {
    if (this.destroyed || this.terminallyDisconnected) {
      throw new Error("Cannot publish from a terminal Publisher");
    }
    this.publishingRequested = true;
    this.logger.debug("startPublishing called");
    const controlGeneration = ++this.publishingControlGeneration;
    return await this.runPublishingReconciliation(controlGeneration);
  }

  public async stopPublishing(): Promise<void> {
    this.logger.debug("stopPublishing called");
    this.cancelPublishingIntent();
    // Pause upstream will stop sending media to the server, while keeping
    // the local MediaStreamTrack active, so the user can still see themselves.
    try {
      await this.waitForTrackOwnershipOperations();
      const results = await Promise.allSettled([
        this.ownMediaOperation(
          this.pauseUpstreams(this.connection.livekitRoom, [
            Track.Source.Microphone,
            Track.Source.Camera,
            Track.Source.ScreenShare,
            Track.Source.ScreenShareAudio,
          ]),
        ),
        this.fencePendingLocalSenders(),
      ]);
      const failure = results.find(
        (result): result is PromiseRejectedResult =>
          result.status === "rejected",
      );
      if (failure) throw failure.reason;
    } finally {
      if (
        this.areSourcesNotSending([
          Track.Source.Microphone,
          Track.Source.Camera,
          Track.Source.ScreenShare,
          Track.Source.ScreenShareAudio,
        ])
      ) {
        this.setPublishingActive(false);
      }
      this.publicationChanged$.next();
    }
  }

  /** Reconciles sender state with MatrixRTC connectivity using exact owners. */
  public async setMatrixRTCConnected(connected: boolean): Promise<void> {
    this.matrixRTCConnected = connected;
    const controlGeneration = ++this.publishingControlGeneration;
    if (!connected) {
      try {
        await this.waitForTrackOwnershipOperations();
        const results = await Promise.allSettled([
          this.ownMediaOperation(
            this.pauseUpstreams(this.connection.livekitRoom, [
              Track.Source.Microphone,
              Track.Source.Camera,
              Track.Source.ScreenShare,
              Track.Source.ScreenShareAudio,
            ]),
          ),
          this.fencePendingLocalSenders(),
        ]);
        const failure = results.find(
          (result): result is PromiseRejectedResult =>
            result.status === "rejected",
        );
        if (failure) throw failure.reason;
      } finally {
        if (
          this.areSourcesNotSending([
            Track.Source.Microphone,
            Track.Source.Camera,
            Track.Source.ScreenShare,
            Track.Source.ScreenShareAudio,
          ])
        ) {
          this.setPublishingActive(false);
        }
        this.publicationChanged$.next();
      }
    } else if (this.publishingRequested) {
      await this.runPublishingReconciliation(controlGeneration);
    }
  }

  public async stopTracks(): Promise<void> {
    const lkRoom = this.connection.livekitRoom;
    const tracks = [...this.ownedTracks].filter((track) =>
      this.ownsTrack(track),
    );

    const results = await Promise.allSettled(
      tracks.map(async (track) => {
        const generation = track.mediaStreamTrack;
        if (!this.getPublishedTracks().has(track)) {
          this.stopOwnedTrackGeneration(track, generation);
          this.releaseStoppedUnpublishedTrack(track);
          return;
        }
        if (hasUnsafePendingTrackMutation(track)) {
          this.stopOwnedTrackGeneration(track, generation);
          return;
        }
        try {
          await this.unpublishTrack(track, lkRoom);
        } finally {
          this.stopOwnedTrackGeneration(track, generation);
        }
        if (this.getPublishedTracks().has(track)) {
          throw new Error("LiveKit retained a stopped local track publication");
        }
        this.releaseStoppedUnpublishedTrack(track);
      }),
    );
    const failure = results.find(
      (result): result is PromiseRejectedResult => result.status === "rejected",
    );
    if (failure) throw failure.reason;
  }

  /// Private methods

  // Restart the audio input track whenever we detect that the active media
  // device has changed to refer to a different hardware device. We do this
  // for the sake of Chrome, which provides a "default" device that is meant
  // to match the system's default audio input, whatever that may be.
  // This is special-cased for only audio inputs because we need to dig around
  // in the LocalParticipant object for the track object and there's not a nice
  // way to do that generically. There is usually no OS-level default video capture
  // device anyway, and audio outputs work differently.
  private workaroundRestartAudioInputTrackChrome(
    devices: MediaDevices,
    scope: ObservableScope,
  ): void {
    const lkRoom = this.connection.livekitRoom;
    devices.audioInput.selected$
      .pipe(
        switchMap((device) => device?.hardwareDeviceChange$ ?? NEVER),
        scope.bind(),
      )
      .subscribe(() => {
        if (
          this.destroyed ||
          this.terminallyDisconnected ||
          lkRoom.state != LivekitConnectionState.Connected
        ) {
          return;
        }
        const activeMicTrack = this.getResumablePublication(
          Track.Source.Microphone,
        )?.track;

        if (
          activeMicTrack &&
          // only restart if the stream is still running: LiveKit will detect
          // when a track stops & restart appropriately, so this is not our job.
          // Plus, we need to avoid restarting again if the track is already in
          // the process of being restarted.
          activeMicTrack.mediaStreamTrack.readyState !== "ended"
        ) {
          this.logger?.info(
            "Restarting audio device track due to active media device changed (workaroundRestartAudioInputTrackChrome)",
          );
          // Restart the track, which will cause Livekit to do another
          // getUserMedia() call with deviceId: default to get the *new* default device.
          // Note that room.switchActiveDevice() won't work: Livekit will ignore it because
          // the deviceId hasn't changed (was & still is default).
          const trackGeneration = this.snapshotTrackGeneration(activeMicTrack);
          const controlGeneration = this.publishingControlGeneration;
          void this.registerTrackGenerationOperation(
            async () => await activeMicTrack.restartTrack(),
            [trackGeneration],
            controlGeneration,
          ).catch(() => {
            this.logger.error("Failed to restart audio device track");
          });
        }
      });
  }

  // Observe changes in the selected media devices and update the LiveKit room accordingly.
  private observeMediaDevices(
    scope: ObservableScope,
    devices: MediaDevices,
    controlledAudioDevices: boolean,
  ): void {
    const lkRoom = this.connection.livekitRoom;
    const syncDevice = (
      kind: MediaDeviceKind,
      selected$: Observable<SelectedDevice | undefined>,
    ): Subscription =>
      selected$.pipe(scope.bind()).subscribe((device) => {
        if (
          this.destroyed ||
          this.terminallyDisconnected ||
          lkRoom.state != LivekitConnectionState.Connected
        ) {
          return;
        }
        // if (this.connectionState$.value !== ConnectionState.Connected) return;
        this.logger.info(`Evaluating LiveKit device sync for ${kind}`);
        if (
          device !== undefined &&
          lkRoom.getActiveDevice(kind) !== device.id
        ) {
          const source =
            kind === "audioinput"
              ? Track.Source.Microphone
              : kind === "videoinput"
                ? Track.Source.Camera
                : undefined;
          const trackGenerations = source
            ? this.getSourceTracks(source).map((track) =>
                this.snapshotTrackGeneration(track),
              )
            : [];
          const controlGeneration = this.publishingControlGeneration;
          const registeredOperation = source
            ? this.registerTrackGenerationOperation(
                async () => await lkRoom.switchActiveDevice(kind, device.id),
                trackGenerations,
                controlGeneration,
              )
            : this.registerMediaOperation(
                lkRoom.switchActiveDevice(kind, device.id),
              );
          void registeredOperation.catch(() =>
            this.logger.error(`Failed to sync ${kind} device with LiveKit`),
          );
        }
      });

    syncDevice("audioinput", devices.audioInput.selected$);
    if (!controlledAudioDevices)
      syncDevice("audiooutput", devices.audioOutput.selected$);
    syncDevice("videoinput", devices.videoInput.selected$);
  }

  /**
   * Observe changes in the mute states and update the LiveKit room accordingly.
   * @private
   */
  private observeMuteStates(): void {
    this.muteStates.audio.setHandler(async (enabled) => {
      return await this.reconcileMuteState(Track.Source.Microphone, enabled);
    });
    this.muteStates.video.setHandler(async (enabled) => {
      return await this.reconcileMuteState(Track.Source.Camera, enabled);
    });
  }

  private async reconcileMuteState(
    source: Track.Source,
    desired: boolean,
  ): Promise<boolean> {
    this.setDesiredSourceEnabled(source, desired);
    try {
      const actual = await this.queueSourceReconciliation(source);
      if (
        this.getDesiredSourceEnabled(source) === desired &&
        actual !== desired
      ) {
        this.setDesiredSourceEnabled(source, actual);
      }
      return actual;
    } catch (error) {
      if (this.getDesiredSourceEnabled(source) === desired) {
        const authoritative =
          source === Track.Source.Microphone
            ? this.muteStates.audio.enabled$.value
            : this.muteStates.video.enabled$.value;
        this.setDesiredSourceEnabled(source, authoritative);
      }
      throw error;
    }
  }

  private getProcessorOperationTrack(
    videoTrack: LocalVideoTrack,
    generation: MediaStreamTrack,
  ): LocalVideoTrack {
    let generations = this.processorOperationTracks.get(videoTrack);
    if (!generations) {
      generations = new WeakMap();
      this.processorOperationTracks.set(videoTrack, generations);
    }
    const existingOperationTrack = generations.get(generation);
    if (existingOperationTrack) return existingOperationTrack;

    const runMutation = async (
      mutation: () => Promise<void>,
    ): Promise<void> => {
      try {
        await this.ownTrackMutationOperation(
          videoTrack,
          generation,
          async (markMutationStarted) => {
            if (
              this.destroyed ||
              this.terminallyDisconnected ||
              !this.ownsTrack(videoTrack) ||
              videoTrack.mediaStreamTrack !== generation ||
              this.getResumablePublication(Track.Source.Camera)?.track !==
                videoTrack
            ) {
              return;
            }
            markMutationStarted();
            await mutation();
            if (this.ownsTrack(videoTrack)) {
              this.recordCurrentSenderAssignments(videoTrack);
            }
          },
        );
      } catch {
        this.logger.error("Failed to update local camera processor");
      }
    };
    const operationTrack = {
      getProcessor: (): ReturnType<LocalVideoTrack["getProcessor"]> =>
        videoTrack.getProcessor(),
      setProcessor: async (
        processor: Parameters<LocalVideoTrack["setProcessor"]>[0],
      ): Promise<void> => {
        await runMutation(async () => {
          await videoTrack.setProcessor(processor);
        });
      },
      stopProcessor: async (): Promise<void> => {
        await runMutation(async () => {
          await videoTrack.stopProcessor();
        });
      },
    } as unknown as LocalVideoTrack;
    generations.set(generation, operationTrack);
    return operationTrack;
  }

  private observeTrackProcessors(
    scope: ObservableScope,
    trackerProcessorState$: Behavior<ProcessorState>,
  ): void {
    const track$ = scope.behavior(
      this.publicationChanged$.pipe(
        startWith(undefined),
        map(() => {
          const track = this.getResumablePublication(
            Track.Source.Camera,
          )?.track;
          return track instanceof LocalVideoTrack
            ? this.getProcessorOperationTrack(track, track.mediaStreamTrack)
            : null;
        }),
        distinctUntilChanged(),
      ),
      null,
    );
    trackProcessorSync(scope, track$, trackerProcessorState$);
  }
}
