import { type LogLevel } from "livekit-client";

interface RageshakeLogger {
  log: (level: LogLevel, loggerName: string, message: string) => void;
}

export function forwardLiveKitLog(
  logger: RageshakeLogger,
  level: LogLevel,
  ..._untrustedProviderData: [message: string, context?: object]
): void {
  logger.log(level, "livekit", "LiveKit diagnostic");
}
